return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'eu','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-21T23:33:36+00:00','po-revision-date'=>'2026-07-05 19:23+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Bideokaitasun anitzeko bidea, SEO anitzeko bidea (hreflang, Open Graph, Schema.org, sitemap), eta AI eduki tresnak WordPress-entzat. Hizkuntzaren detekzioa, URL bidea, itzulpena, edukien sortzea, eta SEO geruza osoa — ez da laguntzaile pluginik behar.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Itzuli','Lingua Forge — Quick Translate'=>'Lingua Forge — Azkar Itzuli','Informative'=>'Informativo','Persuasive'=>'Beldurgarria','Storytelling'=>'Ipuinak','Technical'=>'Teknikoa','Conversational'=>'Egunerokoa','Permission denied.'=>'Baimena ukatua.','Cannot determine target language from slug.'=>'Ezin da helburu hizkuntza zehaztu slug-etik.','Invalid post type.'=>'Post mota baliogabea.','Invalid or primary language.'=>'Hizkuntza baliogabea edo lehenetsia.','Template not found or not stored in the database.'=>'Txantiloia ez da aurkitu edo ez da datu-basean gordeta.','Template has no content.'=>'Txantiloian ez dago edukirik.','No internal links found to update.'=>'Ez da barruko estekarik aurkitu eguneratzeko.','%d link updated.'=>'%d esteka eguneratu da.' . "\0" . '%d esteka eguneratu da.','No language-specific template parts found to map.'=>'Ez da hizkuntza-espezifikoen txantiloia aurkitu mapatzeko.','No template part references needed updating.'=>'Ez da eguneratzeko beharrezkoak diren txantiloia osatzen duten erreferentziarik aurkitu.','%d part reference updated.'=>'%d zatiko erreferentzia eguneratu da.' . "\0" . '%d zatiko erreferentzia eguneratu da.','Invalid language.'=>'Hizkuntza baliogabea.','Template part not found or not stored in the database.'=>'Ez da zatiko osagaiaren zatia aurkitu edo ez da datu-basean gordeta.','Template part has no content.'=>'Zatiko osagaiak ez du edukirik.','No navigation references needed updating.'=>'Ez da nabigazio erreferentziarik aurkitu eguneratzeko.','%d navigation reference updated.'=>'%d nabigazio erreferentzia eguneratu da.' . "\0" . '%d nabigazio erreferentzia eguneratu da.','No AI provider configured.'=>'Ez da AI hornitzaile konfiguratu.','Missing pattern name or language.'=>'Patroiaren izena edo hizkuntza falta da.','Pattern not found.'=>'Ez da patroiarik aurkitu.','Pattern has no content to translate.'=>'Ez du itzultzeko edukirik duen patroiak.','AI provider returned an empty response.'=>'AI hornitzaileak erantzun huts bat eman du.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patroia itzuli eta gorde da. Edukia zure CPT postean kopiatzailearen bidez edo Erabilgarri den Blokearen editorearen bidez erabiltzeko edo hasierako puntua izateko.','%d template repaired.'=>'%d txantiloia konpondu da.' . "\0" . '%d txantiloia konpondu dira.','All template metadata is already up to date.'=>'Datu guztiak eguneratuta daude dagoeneko.','Invalid template type.'=>'Txantiloia mota baliogabea.','Template "%s" already exists.'=>'"%s" txantiloia dagoeneko existitzen da.','Fix Links'=>'Lekuak Konpondu','Fix Parts'=>'Zatiak Konpondu','Re-create'=>'Berreratu','"%s" recreated.'=>'"%s" berreratu da.','"%s" created.'=>'"%s" sortu da.','Invalid template part.'=>'Zati baliogabea.','Template part "%s" already exists.'=>'"%s" zatiko osagaia dagoeneko existitzen da.','Fix Nav'=>'Nabigazioa Konpondu','"%1$s" recreated. %2$d template updated.'=>'"%1$s" berreratu da. %2$d txantiloi eguneratu da.' . "\0" . '"%1$s" berreratu da. %2$d txantiloi eguneratu dira.','"%1$s" created. %2$d template updated.'=>'"%1$s" sortu da. %2$d txantiloia eguneratu da.' . "\0" . '"%1$s" sortu da. %2$d txantiloia eguneratu da.','Page'=>'Orria','Single'=>'Bakarra','Search'=>'Bilatu','Search Results'=>'Bilaketa emaitzak','Archive'=>'Artxibo','Front Page'=>'Orri nagusia','Blog Home'=>'Blog-eko hasiera','Single: %s'=>'Bakarra: %s','Single %s'=>'%s bakarra','Archive: %s'=>'Artxiboa: %s','%s Archive'=>'%s Artxiboa','No source content found to translate.'=>'Ez da itzuli beharreko edukiaren iturririk aurkitu.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Itzuli da. Ikuspegiaren editorean berrikusi — estekak, nabigazio URL-ak eta txantiloiaren slug-ak ez dira automatikoki eguneratzen.','Navigation not found.'=>'Nabigaziorik ez da aurkitu.','Navigation has no content to translate.'=>'Nabigazioak ez du itzuli beharreko edurik.','"%1$s %2$s" saved.'=>'"%1$s %2$s" gorde da.','SEO Analysis'=>'SEO Analisia','Profile'=>'Profila','Details ↗'=>'Xehetasunak ↗','/ 100'=>'/ 100','Overall SEO score'=>'SEO puntuazio orokorra','Metric'=>'Neurketa','Finding'=>'Aurkikuntza','Title'=>'Izenburua','Meta description'=>'Meta deskribapena','Word count'=>'Hitz kopurua','Reading time'=>'Irakurketa denbora','Headings'=>'Goiburuak','Images'=>'Irudiak','Links'=>'Estekak','AI Recommendations'=>'AI gomendioak','Run AI Analysis'=>'Exekutatu AI-analisia','Analyzing…'=>'Aztertzen…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Ezarri AI hornitzailea Ezarpenak → API giltzak atalean AI gomendioak aktibatzeko.','AI analysis failed. Please try again.'=>'AI-analisia huts egin du. Saiatu berriro.','Suggested title'=>'Izenburu proposatua','Suggested meta description'=>'Meta deskribapen proposatua','Loaded from cache.'=>'Kargatuta cache-tik.','↺ Refresh AI Analysis'=>'↺ Berrabiatu AI-analisia','Analyse…'=>'Aztertu…','Analysis request failed. Please try again.'=>'Analisia eskaera huts egin du. Saiatu berriro.','No translation found — analyzed the source language version.'=>'Ez da itzulpenik aurkitu — iturri hizkuntzaren bertsioa aztertu da.','Translate page…'=>'Orriaren itzulpena…','Generate content…'=>'Edukia sortu…','AI Behaviour Preset'=>'AI portaeraren aurrebista','Custom'=>'Pertsonalizatua','Global default (%s)'=>'Guztizkoa lehenetsia (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Itzulpenean eta Edukiaren generazioan AI aurrebista hau erabiltzen du. Gune osoan ezarritako prompt-instrukzioak (Ezarpenak → Portaera) beti gehitzen dira eskaera bakoitzean, aukeraketa honetatik haratago.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Itzulpenean eta Edukiaren generazioan AI aurrebista hau erabiltzen du. Beste ezaugarri guztiak beti erabiltzen dute aurrebista globala.','Close'=>'Itxi','Translate missing'=>'Itzuli falta','From'=>'Nondik','Retranslate'=>'Itzuli berriro','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Itzuli beste hizkuntza-bertsio guztiak argital honetik. Sortzen du ez daudenak eta gainidazten du dagoeneko daudenak — hasierako hizkuntza barne, argital hau itzulpena bada.','Sync'=>'Sinkronizatu','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Esleitu zuzena den hizkuntza-espezifikoa txantiloia argital honen itzulpen-bertsio guztiari. Ez da AI deiketarik eta ez dira eduki-aldaketak — libre eta segura exekutatzeko edozein unetan.','Template Sync — reassign templates for every translation'=>'Txantiloi Sinkronizazioa — txantiloak esleitu itzulpen guztientzat','TS'=>'TS','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Azken SEO puntuazio oinarritua. Exekutatu azterketa Ezarpenak → SEO → Azterketa atalean eguneratzeko.','Translating…'=>'Itzultzen…','Retranslating…'=>'Itzuli berriro…','Syncing…'=>'Sinkronizatzen…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Honek argital honen hizkuntza-bertsio guztiak berriz itzultzen ditu honetik — ez daudenak sortzen eta dagoeneko daudenak gainidazten (hasierako hizkuntza barne, argital hau itzulpena bada). Ezin daiteke desegin. Jarraitu?','Syncing templates…'=>'Txantiloak sinkronizatzen…','✓ Done'=>'✓ Eginda','Error'=>'Errorea','Navigation posts are translated via the Router tab, not this button.'=>'Nabigazio postak Router fitxan itzuliak dira, ez botoi honetan.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Post mota "%s"entzako itzulpenak sortzea aktibo dagoen integrazio bat behar du. Mesedez, ziurtatu integrazio beharrezkoa instalatuta eta aktibo dagoela.','No %s version found in this translation group.'=>'Ez da %s bertsio hau itzulpen talde honetan aurkitu.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'Hizkuntza sekundarioan dagoen WooCommerce produktutik sinkronizatzea desgaituta dago berez, produktu primarioa gainidaztuko lukeelako. Gaitu Settings → Behavior → WooCommerce atalean itzulpena iturburuko eduki berri bihur daitezala nahi baduzu.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'Hizkuntza sekundarioan dagoen argitalerraren ondotik sinkronizatzea desgaituta dago berez, argital primarioa gainidaztuko lukeelako. Gaitu Settings → Behavior → Sync atalean itzulpena iturburuko eduki berri bihur daitezala nahi baduzu.','Skipped — you do not have permission to edit the existing translation.'=>'Baztertuta — ez duzu baimena dagoen itzulpena editatzeko.','Creating translations for post type "%s" requires an active integration.'=>'"%s" argital-motarako itzulpenak sortzeak aktibo integrazio baten beharra du.','Template Sync can only be run from the primary/source-language post.'=>'Txantiloi Sinkronizazioa hasierako/iturburuko-hizkuntzako argitaletik soilik exekuta daiteke.','Skipped — you do not have permission to edit this translation.'=>'Baztertuta — ez duzu baimena itzulpen hau editatzeko.','Translation Caching'=>'Itzulpenaren cachea','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge-k bi cache geruza independente erabiltzen ditu AI API deien errepikapenak saihesteko. Erabil itxaronen azpi-atalak bakoitza aztertu eta kudeatzeko.','API Response Cache'=>'API Erantzun Cachea','Translation Memory'=>'Itzulpen Memoria','(disabled)'=>'( desgaituta)','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Post bakoitzeko cachea AI-k sortutako itzulpenak, meta-deskribapenak, laburpenak eta edukia. Sarrera automatikoki baliogabetzen da edukia edo AI hornitzailea/modeloa aldatzen denean.','Enable API response caching'=>'Gaitu API erantzun cachea','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'API Erantzun Cacheak AI eskaeraren emaitza gordetzen du — itzulpena, meta-deskribapena, laburpena eta edukia — sarrera hash baten bidez giltzatuta (edukia, hizkuntza bikotea, hornitzailea, modeloa). Gaitu ezazu prompt tuning-ean edo eskaera bakoitza AI hornitzailearengana iristeko behar duzunean. Desgaitzeak cacheko sarrerak ezabatzen ez ditu, berriro aktibatzeak berreskuratzen ditu.','Save'=>'Gorde','Cached API responses'=>'Cacheatutako API erantzunak','API calls saved by cache'=>'Cache bidez gorde diren API deiak','(avg %.1f hits/entry)'=>'(batez beste %.1f deialdi/entry)','Oldest cached response'=>'Cacheatutako erantzun zaharrena','Most recent cached response'=>'Cacheatutako erantzun azkena','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Ezabatu cacheko AI emaitza guztiak? Etorkizuneko eskaerak API deien berriro exekutatzen ditu cachea berritzen den arte.','Clear API Response Cache'=>'Ezabatu API Erantzun Cachea','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Bloke mailako itzulpen cachea, post guztietan partekatua. Gaituta, bloke berdinak (markaketa, hizkuntza bikotea, glosarioa) memoriaetik zerbitzatzen dira AI berriro deitu gabe. Glosarioaren editaketak eta Konplaintzaren aurreko ezarpenak automatikoki baliogabetzen dituzte cacheko itzulpenak.','Enable block-level translation cache reuse across posts'=>'Gaitu bloke mailako itzulpen cachearen berrerabilpena post guztietan','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Une honetan ez da erabiltzen, bloke-argazki atributu placeholder-ak (wp:details laburpen eremuak, etab.) erabiltzen dituzten postetan — existitzen den deialdi bakarreko itzulpen bideari jarraitzen diote.','Cached block translations'=>'Cacheatutako bloke itzulpenak','Block translation reuses'=>'Bloke itzulpen berrerabiltzen','(avg %.1f hits/block)'=>'(batez beste %.1f deialdi/bloke)','Oldest cached block'=>'Cacheatutako bloke zaharrena','Most recent cached block'=>'Cacheatutako bloke azkena','Approximate size'=>'Tamaina aproximatua','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Ezabatu Itzulpen Memoria osoa? Etorkizuneko itzulpenek cachea berriro eraikiko dute euren exekuzioan.','Clear Translation Memory'=>'Ezabatu Itzulpen Memoria','API Response Cache setting saved.'=>'API Erantzun Cachearen ezarpena gorde da','Translation Memory setting saved.'=>'Itzulpen Memoriaren ezarpena gorde da','AI cache cleared. %d entry was removed.'=>'AI cachea ezabatu da. %d sarrera ezabatu da.' . "\0" . 'AI cachea ezabatu da. %d sarrera ezabatu dira.','Translation Memory cleared. %d cached block was removed.'=>'Itzulpen Memoria ezabatu da. %d cacheatutako blokea ezabatu da.' . "\0" . 'Itzulpen Memoria ezabatu da. %d cacheatutako blokek ezabatu dira.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge osatutako anitzeko SEO soluzioa da. Ez du SEO plugin gehigarririk behar.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'SEO plugin orokorrak instalatuta baduzu, panel honek LF nola egokitzen den erakusten du output bikoitza saihesteko. Helburua talka saihestea da — ez lankidetza. LF beti ematen du hizkuntzen aniztasun SEO geruza (hreflang, og:locale, inLanguage schema) behar duena, LF-ren hizkuntza bidearen konfigurazioaren ezagutza behar duena.','Installed SEO plugins'=>'SEO plugin instalatuak','Plugin'=>'Plugin','Status'=>'Egoera','✓ Active'=>'✓ Aktiboa','— Not detected'=>'— Ez da detektatu','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Ez dago kontrako SEO pluginik detektatu. Lingua Forge-k SEO irteera guztia modu independentean kudeatzen du.','What LF provides — and collision avoidance'=>'LF-k ematen duena — eta talka saihestea','Feature'=>'Ezaugarri','LF provides'=>'LFk ematen du','When another SEO plugin is installed'=>'Beste SEO plugin bat instalatuta dagoenean','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Desaktibatuta (ezarpen bidez)','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF irteerak — plugin hreflang ezabatuta','✓ LF outputs'=>'✓ LF irteerak','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LFk eraginkortasunez ematen du hreflang denak konfiguratutako hizkuntzarako, x-default barne. SEO plugin orokorrak ez du zure LF bideratze konfigurazioan sarbiderik eta hreflang akats URL okerretan oinarrituta sortuko luke. LF haien irteera ezabatzen du iragazki bidez talka ekiditeko.','Suppressed: %s.'=>'Ezgaitu da: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Desaktibatuta (modu ezarpen bidez)','→ Locale tags only — deferring base OG to plugin'=>'→ Tokiko etiketak soilik — oinarri OG atzeratzen plugin-era','→ Locale tags only (manual setting)'=>'→ Tokiko etiketak soilik (eskuzko ezarpena)','✓ LF outputs full OG + Twitter Cards'=>'✓ LF irteerak OG osoa + Twitter Cards','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF beti gehitzen du og:locale eta og:locale:alternate — hizkuntza anitzeko OG seinaliak ez duela plugin orokor batek zuzenean sortu. Oinarrizko OG multzoa (og:title, og:description, og:image) ematen du plugin gabe dagoenean. SEO plugin bat instalatuta badago, LF-k multzo nagusia saihesten du bikoizketa etiketa sortzeko — ez pluginak "hobe" direlako, baina bikoizketa ez duelako baliorik sortzen.','Schema.org JSON-LD'=>'Schema.org JSON-LD','— Deferred to plugin'=>'— Pluginera atzeratua','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF irteerak Artikulua / Web orria / Webgunea','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LFk JSON-LD anitz hizkuntzazkoak ematen ditu hizkuntza anotazioekin, bere bideratze konfigurazioarekin lotuta. SEO plugin bat instalatuta dagoenean, LFk bere schema guztiz desgaitu egiten du: JSON-LD grafiko bikoitzek baliozkotze erroreak sortzen dituzte eta grafiko existitzen bati osagarri bat jartzeko modu garbirik ez dago.','XML Sitemap'=>'~%d minutuko irakurketa','✓ Active at /lf-sitemap.xml'=>'✓ Aktiboa /lf-sitemap.xml-n','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF-k bere sitemap propioa sortzen du xhtml:link alternatibekin denbora-talde guztientzat. SEO plugin bat instalatuta badago, sitemap bereizi bat sortzen du — biak independente daude. Bidali biak Google Search Console-era: SEO pluginaren sitemap edukia aurkitzeko, LF-ren sitemap hizkuntza erlazio seinalerako.','Canonical tag'=>'Kanonikoa etiketa','✓ WP canonical replaced (self-referencing)'=>'✓ WP canonical ordeztu da (norberaren erreferentzia)','WP core canonical active (hreflang disabled)'=>'XML Sitemap','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF WordPressen erro kanonikoa ezabatzen du eta berreskuratzen du norberaren erreferentziazko kanonikoa zuzenean URLaren hizkuntza-prefixedarekin. Hirugarren bateko SEO plugin batek (Yoast, Rank Math, AIOSEO, SEOPress) aktibuta dagoenean, LF kanonikoaren kudeaketa plugin horretara uzten du guztiz.','Legacy lf-social-share mu-plugin'=>'Legacy lf-social-share mu-plugin','The lf-social-share mu-plugin is active.'=>'lf-social-share mu-plugin aktibo dago.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Lingua Forge-ren Gizarte Partekatze eta Open Graph moduluak mu-plugin-ek eskaintzen duen funtzionalitatea guztia estaltzen du, baita og:locale anitzak ere. Seguru dezakezu mu-plugina desgaitu dezakezula.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card etiketak: LF-ren Open Graph moduluak kudeatzen du (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Gizarte Ikonoen blokea partekatzea: URL-ak: LF-ren Gizarte Partekatze (SEO → Gizarte Partekatze) eraikitakoak','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'kopiatu/natibo/auto JS ekintzak: LF-ren social-share.js-k kudeatzen ditu','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'WooCommerce','Debug Files'=>'Debug Fitxategiak','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Debug log-ak aktibatuta dagoenean (beheko toggle bidez edo wp-config.php-n LINGUAFORGE_AI_DEBUG definituz), Itzulpen eta FSE txantiloi itzulpen ezaugarriak AI prompt eta erantzunak diskoan idazten dituzte arazteak egiteko. Erabili atal hau irteera hori monitorizatzeko eta garbitu behar duzunean — fitxategiak azkar handitzen dira orri handietan. Konfiguratu helbide direktorioa linguaforge_debug_dir iragazkiaren bidez.','Debug files cleared. %d file was removed.'=>'Debug fitxategiak garbitu dira. %d fitxategi bat kendu da.' . "\0" . 'Debug fitxategiak garbitu dira. %d fitxategi kendu dira.','Debug logging enabled.'=>'Debug log-ak aktibatuta daude.','Debug logging disabled.'=>'Debug log-ak desaktibatuta daude.','Debug logging'=>'Debug log-ak','Write AI prompts and responses to disk for troubleshooting'=>'AI prompt eta erantzunak diskoan idaztea arazteak egiteko','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Linguaforge_AI_DEBUG konstanteak wp-config.php-n behartu du. Lerro hori ezabatu toggle hau kontrolatzeko hemen.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Linguaforge_AI_DEBUG konstanteak wp-config.php-n behartu du. Lerro hori ezabatu toggle hau kontrolatzeko hemen.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Fitxategiak beheko direktorian kokatzen dira. Itzulpen arazoak diagnostikatzeko erabilgarria — itzali behar duzu behar duzuna lortu arte, bestela fitxategiak handitzen dira. Hau behartu dezakezu wp-config.php-tik `define( \'LINGUAFORGE_AI_DEBUG\', true );` erabiliz, toggle hori gainetik.','Currently:'=>'Unean','✓ Enabled'=>'✓ Aktibatuta','✗ Disabled'=>'✗ Desaktibatuta','Directory'=>'Direktorioa','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtro linguaforge_debug_dir erabiliz, debug irteera ezkutatzeko ezkutatzen den lekura bideratuz.','Files'=>'Fitxategiak','.txt file(s) in the directory'=>'.txt fitxatega(ak) direktorioan','Save Debug Setting'=>'Gorde Debug Ezarpena','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Ezabatu direktorioan dauden .txt fitxategi guztiak? Direktorioa bera geratuko da, beraz etorkizuneko debug idatziak garbi iristen jarraituko dute.','Clear Debug Files'=>'Garbitu Debug Fitxategiak','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge-k <link rel="alternate" hreflang> etiketa guztiak sortzen ditu hizkuntza konfiguratu guztietarako orri bakoitzean, x-default barne, iturri hizkuntzara zuzenduta. Hori da Google eta beste bilaketa-motorentzako SEO seinalea nagusia — ez da plugin SEO gehigarririk behar.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Yoast SEO, Rank Math, All in One SEO edo SEOPress aktibo dagoenean, Lingua Forge-k automatikoki ezabatzen ditu haien hreflang irteerak iragazki bidez. SEO plugin orokorrak URL egitura bakarrean oinarritutako hreflang sortzen dute eta ez dute zure anitzeko hizkuntzaren konfigurazioa kontuan hartzen; LF-ren irteera beti zuzena da.','Hreflang settings saved.'=>'Hreflang ezarpenak gorde dira.','Hreflang output'=>'Hreflang irteera','Output hreflang tags in wp_head'=>'Irteerako hreflang etiketa wp_head-n','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Desaktibatu soilik headless guneentzat edo hreflang inplementazio oso pertsonalizatuentzat. Desaktibatuta, LF ez da WordPressen kanonikoa etiketa kentzen eta ez da SEO pluginen hreflang irteerak ezabatzen.','Current status'=>'Uneko egoera','✓ Hreflang active'=>'✓ Hreflang aktiboa','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF-k hreflang etiketa irteten ditu eta WordPressen kanonikoa ordezten du hizkuntza bakoitzeko kanoniko erreferentziala erabiliz.','LF is suppressing hreflang output from: %s'=>'LF-k honetatik irteten du: %s','Save Hreflang Settings'=>'Gorde Hreflang ezarpenak','Language Overrides'=>'Hizkuntzaren gaineko aldaketak','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Igo itzulpen .mo fitxategiak hirugarren aldeko pluginen testuetan ordezkatzeko — adibidez, VikBooking itzulpen pertsonalizatua "suit" ordez "gela" erabiltzen duena. Fitxategiak WordPressen izenburuaren arauak jarraitu behar dute: {textdomain}-{locale}.mo (adibidez, vikbooking-ca.mo). Uploads karpetan gordetzen dira eta plugin eguneraketak iraun dezakete.','Override file uploaded successfully.'=>'Ordezko fitxategia arrakastaz igo da.','Override file deleted.'=>'Ordezko fitxategia ezabatu da.','No file was selected.'=>'Ez da fitxategirik aukeratu.','Only .mo files are accepted.'=>'Only .mo fitxategiak onartzen dira.','The upload failed — please try again.'=>'Igoera huts egin da — saiatu berriro.','Could not save the file. Check that the uploads folder is writable.'=>'Ez da fitxategia gorde. Egiaztatu igoerak karpetak idazteko moduan daudela.','Invalid filename.'=>'Fitxategi izenburu baliogabea.','Security check failed — file path is not permitted.'=>'Segurtasun egiaztapena huts egin da — fitxategi bidea ez da baimendua.','An unknown error occurred.'=>'Errore ezezaguna gertatu da.','Text domain / locale'=>'Testu domeinua / hizkuntza','Size'=>'Tamaina','Delete all files for this override (both .mo and .po)?'=>'Ezabatu fitxategi guztiak ordezkaritza honetan (biak .mo eta .po)?','Delete'=>'Ezabatu','No override files uploaded yet.'=>'Oraindik ez da ordezkaritza fitxategirik igo.','Upload .mo file'=>'Igo .mo fitxategia','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Only compiled .mo fitxategiak onartzen dira. Fitxategiak {textdomain}-{locale}.mo eredua jarraitu behar du. Fitxategi batek izen bera badu beste batekin, ordezkatu egingo da.','Upload Override'=>'Igo Ordezkoa','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiatu Segurtasun Gordailura','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate-k bere itzulpen pertsonalak wp-content/languages/loco/ kokatzen ditu — leku hori WP eguneraketak, plugina berrabiarazteak edo Loco Translate bera ezabatzeak ezabatzen du. Fitxategiak hemen kopiatzeak Lingua Forge i18n-overrides direktorioan jartzen ditu, eta horrek iraun egiten du eta automatikoki kargatzen da eskaera bakoitzean.','File copied to safe storage successfully.'=>'Fitxategia arrakastaz kopiatuta segurtasun gordean.','Source file not found.'=>'Iturri fitxategia ez da aurkitu.','Could not copy the file. Check that the uploads folder is writable.'=>'Ez da fitxategia kopiatzen. Egiaztatu igoerak karpetak idazteko moduan daudela.','Invalid file reference.'=>'Fitxategi erreferentzia baliogabea.','Type'=>'Mota','✓ In safe storage'=>'✓ Segurtasun gordailuan','Copy to safe storage'=>'Kopiatu segurtasun gordailura','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Oraindik ez da Loco Translate fitxategirik aurkitu. Itzulpen bat gordetzen duzunean, hemen agertzen da.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge-k Open Graph eta Twitter Card meta etiketa irteten ditu, URL partekatuek hizkuntza, izenburua, deskribapena eta irudia sozial plataformetan zuzenean erakusteko.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Hreflang-en kontrakoa — LF beti gainidazten du beste pluginak, haiek ez baitakite zure anitzeko hizkuntzaren konfigurazioa — Open Graph desberdina da: Yoast, Rank Math eta antzeko pluginek dagoeneko irteera egokia ematen dute zure edukirako OG etiketa. Bikoiztea ez du baliorik. Modu automatian, LF aktibo dauden SEO pluginak detektatzen ditu eta gehitzen duena soilik: og:locale (egungo hizkuntza) eta og:locale:alternate (beste hizkuntza guztiak).','Open Graph settings saved.'=>'Open Graph ezarpenak gorde dira.','Open Graph output'=>'Open Graph irteera','Output Open Graph tags in wp_head'=>'Open Graph etiketen wp_head-en irtezi','Output mode'=>'Irteeraren modua','Auto (recommended)'=>'Auto (gomendatua)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Detektatu aktibo dauden SEO pluginak (Yoast, Rank Math, etab.) exekuzioan. Eman og:locale + og:locale:alternate bakarrik beste plugin batek dagoeneko ematen badu OG multzo osoa; eman multzo osoa ez bada detektatzen.','Locale only'=>'Bakarrik locale','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Betiko eman og:locale eta og:locale:alternate bakarrik. Erabili beste plugin edo gaia OG multzo osoa kudeatzen duenean.','Full'=>'Bakarra','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Betiko eman OG + Twitter Card multzo osoa beste pluginak ematen badu ere. Erabili bakarrik plugin batek OG etiketen irteera ematen ez badu.','Disabled'=>'Desaktibatu','Do not output any OG tags.'=>'Ez eman OG etiketa inon.','Default OG image'=>'OG irudi lehenetsia','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Orri batek ez badu irudi nabarmena, logo edo ikonoa, URL alternatiboa erabiltzen da. Gaur egungo sozialetako aurreikuspenetan erakusten da artxibo, blogaren hasiera eta orri singular batean, thumbnail gabe.','— Disabled'=>'— Desaktibatu','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktibo — locale etiketa bakarrik (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Aktibo — OG + Twitter Card guztiak','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Legacy lf-social-share mu-plugin detektatu da. LF-k OG multzoaren oinarria mu-plugin-era atzeratzen du eta og:locale + og:locale:alternate bakarrik ematen du. Mu-plugina deaktibatu dezakezu — LF-ren Gizarte Partekatze (SEO → Gizarte Partekatze fitxa) eta Open Graph-k funtzionalitate bera dute.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEO plugin(a) detektatu da: %s. LF-k og:locale eta og:locale:alternate bakarrik ematen ditu; detektatutako pluginak OG multzo osoa kudeatzen du.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Ez da kanpoko OG pluginik detektatu. LF-k OG + Twitter Card multzo osoa ematen du.','Save Open Graph Settings'=>'Gorde Open Graph konfigurazioak','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge-k Schema.org JSON-LD egituratutako datuak sortzen ditu, bilatzaileek zure edukien mota, hizkuntza eta metadatuak ulertzeko. Hau da Google eta beste bilatzaileentzat hizkuntza anitzeko edukien adierazpenak komunikatzeko modurik nagusia.','Schema output deferred.'=>'Schema output atzeratu da.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s aktibo dago eta dagoeneko Schema.org JSON-LD ematen du. Lingua Forge-k bere schema irteera desgaitu du grafiko gatazkak saihesteko. Open Graph-en bezala — LF-k og:locale gehitzen du beste plugin baten irteera gainean — schema ez da modu garbian osatu daitekeena: JSON-LD grafiko bikoitz edo gainjarriak erroreak sortzen dituzte balidazioan. Desgaitu schema irteera detektatutako plugin-an, LFk egituratutako datuak kude dezan.','Schema.org settings saved.'=>'Schema.org konfigurazioak gorde dira.','Schema.org output'=>'Schema.org irteera','Output Schema.org JSON-LD in wp_head'=>'Schema.org JSON-LD irteera wp_head-en','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Blokeatuta — plugin bat kontrako SEO plugin aktibo dago. Ikusi goiko oharra.','Article / WebPage'=>'Artikulua / WebOrria','Output Article or WebPage schema on singular posts and pages'=>'Irteera Artikulua edo WebOrri schema singular post eta orrietan','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Blogeko postak Artikulua erabiltzen du; beste post mota eta orriak WebOrri. Titulua, deskribapena, inLanguage, url, argitaratze data, aldatze data, irudi eta argitaratzailea barne.','WebSite'=>'WebSite','Output WebSite schema on the front page and blog index'=>'Irteera WebSite schema hasierako orrian eta blogaren hasierako orrian','Includes site name, url, and inLanguage.'=>'Baliokide izena, url eta inLanguage barne.','Product'=>'Produktua','Output Product schema on WooCommerce product pages'=>'Irteera Produktu schema WooCommerce produktuen orrietan','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Izena, deskribapena, inLanguage, url, irudi eta eskaintza batekin prezioa, prezio moneta eta eskuragarritasuna barne. Prezioa eta eskuragarritasuna iturri-hizkuntzako produktutik datoz (stock eredua partekatua).','Currently emitting'=>'Une honetan emititzen','Article / WebPage — all singular posts and pages'=>'Artikulua / WebOrria — post eta orri singular guztiak','WebSite — front page / blog index'=>'WebSite — hasierako orria / blogaren hasierako orria','Product — WooCommerce product pages'=>'Produktua — WooCommerce produktuen orriak','Nothing — all types disabled'=>'Ez da ezer — mota guztiak desgaituak','Save Schema.org Settings'=>'Gorde Schema.org konfigurazioak','Blog / Editorial'=>'Blog / Editorial','Product / eCommerce'=>'Produktua / eCommerce','Landing / Short-form'=>'Landa / Labur-forma','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtroa hizkuntzaren eta post motaren arabera, zure edukia arakatu, eta edozein elementu aztertu SEO audit bat egiteko arau-oinarritutako — titulua, meta deskribapena, hitzen kopurua, goiburu egitura, irudiaren alt estaldura, eta barneko estekak.','Treat H2 as H1 equivalent'=>'Treat H2 as H1 equivalent','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Gaitu zure gaia postaren titulua H2 bezala renderizatzen duenean (batzuetan bloke gaien artean ohikoa). Analiszaileak orri renderizatua hartzen du eta, H1 ez badago baina H2 badago, lehen H2 H1-ra igotzen du puntuatzeko.','Save analysis settings'=>'Gorde analisi konfigurazioak','Per-Post Analysis'=>'Post bakoitzeko analisia','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Aukeratu post bat eta exekutatu SEO azterketa xehea, eta ikusi metricako emaitzak eta puntuazioa elementu horretarako.','Language'=>'Hizkuntza','source'=>'iturria','All types'=>'Mota guztiak','Load content'=>'Kargatu edukia','Batch Analysis'=>'Analisia sorta','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Egiten SEO azterketa osoa argitaratutako post guztietan, edo aktibo dauden hizkuntzetan. Puntuazioak post bakoitzean gordetzen dira eta hizkuntzaren zutabeko ikonoetan islatzen dira.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'WooCommerce sistemako orriak (Denda, Saskia, Ordaindu, Nire Kontua) ez dira barne hartzen — haien edukia WooCommercek kudeatzen du eta SEO editorekin hobetu ezin daiteke.','Post type'=>'Post motak','Default profile'=>'Profila lehenetsia','— Auto-detect —'=>'— Auto-detektatu —','Analyse all languages'=>'Hizkuntza guztiak aztertu','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Auto-detektazioak esleitzen du: WooCommerce produktuak → Produktu profila; aurrealde estatikoa → Landa profila; gainerako guztia → Blog profila. Aukeratu profila zehatz bat hau guztientzat gainditzeko.','%d post'=>'%d post' . "\0" . '%d post','Last run: %s ago'=>'Azken exekuzioa: %s ordu batzuk dira','Never run'=>'Ez da inoiz exekutatu','avg'=>'ertaina','(partial)'=>'(partziala)','Analyse'=>'Aztertu','(no title) #%d'=>'(ez du izenbururik) #%d','Invalid post ID.'=>'Post ID baliogabea.','Post not found or not published.'=>'Posta ez da aurkitu edo ez da argitaratu.','~%d min read'=>'~%d minutu irakurtzeko' . "\0" . '~%d minutu irakurtzeko','No title set.'=>'Ez da izenbururik ezarri.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Izenburua %1$d karaktere ditu — SERPetan laburra izan daiteke (%2$d azpitik saiatu).','Title is only %d chars — aim for at least 10 characters.'=>'Izenburua %d karaktere ditu — gutxienez 10 karaktere izan beharko lituzke.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Hitz bakarreko izenburua (%d karaktere) — bigarren hitz bat gehitzeak argitasuna eta gako-hitzak hobetzen ditu.','%1$d chars, %2$d words — good title.'=>'%1$d karaktere, %2$d hitz — izenburu ona.','Using LF AI meta description.'=>'LF AI meta deskribapenaren erabilera.','No LF meta description set — using excerpt/content.'=>'Ez da LF meta deskribapenik ezarri — laburpen edo edukia erabiltzen ari da.','No meta description found. Generate one via the AI meta description feature.'=>'Ez da meta deskribapenik aurkitu. Sortu AI meta deskribapenaren ezaugarriarekin.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d karaktere — oso laburra (%2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d karaktere — SERPetan agian moztuta egongo da (%2$d azpitik). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d karaktere — ona, pixka bat gainditzen du idealeko %2$d baina barne hartzen du onartutako %3$d karaktere tartea. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d karaktere — luzera ideala. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d hitz — edukia oso mehea. Kontuan hartu gutxienez %2$d hitz gehitzeko.','%1$d words — below recommended minimum of %2$d.'=>'%1$d hitz — gomendatutako minimoaren azpitik %2$d.','%d words.'=>'%d hitz.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-H1 modua aktibatuta — izenburua H1 baliokide gisa kontatzen da. (Goiburuen etiketak ezin izan dira detektatu orriaren renderizazioan; egiaztatu zure gaia izenburua behar bezala ateratzen duela.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Ez da H1 aurkitu. Normalean, postaren izenburua H1 da — egiaztatu zure gaia hori ateratzen duela.','%d H1 tags found — a page should have exactly one H1.'=>'%d H1 etiketa aurkitu da — orri batek zehazki H1 bat izan behar du.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — ez da H2, baina %d H3 azpi-izenburu aurkitu dira (adibidez, accordion/ xehetasunetako goiburuak). Egitura onargarria da.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — edukia laburra (%d paragrafo), azpi-izenburuak ez dira beharrezkoak.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — ez da H2 azpi-izenburuak aurkitu. (Edukiera mota honentzat onargarria da.)','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — ez da H2 edo H3 azpi-izenburuak aurkitu. H2ak gehitzea egitura hobetzen du.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'Ez da irudiak aurkitu edukian.','%1$d of %2$d image(s) missing alt text.'=>'%1$d irudi %2$d irudi falta daude alt testua.','%d image(s), all have alt text.'=>'%d irudi, guztiak alt testuarekin.','No links found. Internal links improve crawlability and user navigation.'=>'Ez dago loturarik aurkitu. Lotura barnekoak nabigazioa eta nabigazioaren eraginkortasuna hobetzen dute.','No links found.'=>'Ez dago loturarik aurkitu.','%d external link(s), no internal links. Add internal links to related content.'=>'%d kanpoko lotura, ez barneko loturarik. Gehitu lotura barnekoak edukiarekin lotuta.','%d external link(s), no internal links.'=>'%d kanpoko lotura, ez barneko loturarik.','%1$d internal, %2$d external.'=>'%1$d barneko, %2$d kanpoko.','Post not found.'=>'Posta ez da aurkitu.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Ez dago AI hornitzaile konfiguraturik. Gehitu API giltza Ezarpenak → API Giltzak atalean.','No response from AI provider. Check your API key and try again.'=>'Ez dago AI hornitzailearen erantzunik. Egiaztatu zure API giltza eta saiatu berriro.','AI returned an unexpected response format. Please try again.'=>'AIak erantzun ezusteko formatu bat eman du. Saiatu berriro.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge-k XML mapa bat sortzen du /lf-sitemap.xml helbidean, eta hizkuntza alternatibako loturak gehitzen ditu zure itzulitako edukirako. Mapak WordPressen mapa nagusia eta SEO pluginen mapa osatzen ditu — ez ditu ordezkatzen.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'WordPressen mapa nagusia zure edukien URL guztiak zerrendatzen ditu. LF mapa hizkuntza bertsioek nola erlazionatzen diren adierazten du xhtml:link hreflang alternatibekin. Bidali biak Google Search Console-era estaldura osoa lortzeko.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s aktiboa da eta bere mapa propioa sortzen du. Mapak LF-renak baino bereiziagoa da. Biak bidali Google Search Console-era: SEO pluginaren mapa zure edukia zerrendatzen du; LF mapa hizkuntza anitzeko loturak gehitzen ditu. LF-ren mapa automatikoki iragartzen da robots.txt-n.','Sitemap settings saved.'=>'Mapa egokitzapenak gorde dira.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Mapa cachea hustu da. Hurrengo bisitan mapa helbidean berriz sortuko da.','Sitemap output'=>'Mapa emaitza','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Sortu hizkuntza anitzeko mapa /lf-sitemap.xml helbidean','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Gaituta, mapa helbidea automatikoki iragartzen da robots.txt-n eta cachea eguneratzen da itzulitako edukia gordetzen denean.','Sitemap URL'=>'Mapa helbidea','Submit this URL to Google Search Console alongside your main sitemap.'=>'Bidali helbide hau Google Search Console-era zure maparekin batera.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Oraindik sortu gabe. Mapak lehen bisitan sortzen da eta 24 orduz cachean gordetzen da.','✓ Active — %d URL entry with language alternates'=>'✓ Aktiboa — %d URL sarrera eta hizkuntza alternatibak' . "\0" . '✓ Aktiboa — %d URL sarrera eta hizkuntza alternatibak','No translated content found. The sitemap will populate once posts have been translated.'=>'Ez dago itzulitako edukirik aurkitu. Mapak beteko dira posta itzulitakoak izan direnean.','Last generated: %s'=>'Azkeneko eguneraketa: %s','Save Sitemap Settings'=>'Gorde Maparen Ezarpenak','Flush Sitemap Cache'=>'Hustu Maparen Cachea','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Bultzada ematen dio mapak hurrengo eskaeran berriz sortzeko. Erabili masiboki inportatu edo itzulpen erlazioak eskuz editatu ondoren.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow protokolo irekia da, Bing, Yandex eta beste bilaketa-motorrek onartzen dute. Post bat itzulita edo eguneratuta, Lingua Forge-k automatikoki jakinarazten die motor guztiei — ez dago polingik, ez itxaron robotak.txtaren arakatze hurrenkerara.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow-k ordeztu du Bing eta Yandexen mapa-ping endpoints zaharra. Google-k mapak ezagutzen ditu robots.txt Sitemap: direktiboa erabiliz, aurreko moduan.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Guztiz URLak IndexNow-era bidali dira arrakastaz.','No translated URLs found to submit. Publish some translated posts first.'=>'Ez dago bidaltzeko itzulitako URLik. Lehenik, posta itzulitako batzuk argitaratu.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ IndexNow bidalketa huts egin du. Egiaztatu giltza fitxategia publikoan dagoela (ikus behean) eta saiatu berriro.','Verification key'=>'Egiaztapen giltza','Key file served automatically at: %s'=>'Giltza fitxategia automatikoki zerbitzatzen da: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Giltza ezin izan da sortu. Egiaztatu WordPress aukerak idazteko aukera duela.','Key file status'=>'Giltza fitxategiaren egoera','✓ Key file is publicly reachable.'=>'✓ Giltza fitxategia publikoan dagoela.','✗ Key file is not reachable.'=>'✗ Giltza fitxategia ez da iristekoa.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'IndexNow motorrek giltza fitxategia egiaztatzen dute aurretik eskaerak onartzeko. Fitxategia ez bada iristekoa, eskaerak 403 errorearekin baztertuko dira.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Arrazoi ohikoak: cache osoa (garbitu), segurtasun plugin batek .txt fitxategiak blokeatzen ditu, edo Nginx/Apache arau pertsonalizatua. Fitxategia LF-k zerbitzatzen du eskaera bakoitzean — ez dago fitxategi fisikorik diskoan.','Submit all URLs'=>'Bidali URL guztiak','Submit all URLs via IndexNow'=>'Bidali URL guztiak IndexNow bidez','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Bidali denbora guztian, LF-k kudeatutako URL guztiak IndexNow-era inbentariatzen ditu. Bidalketa automatikoa denbora guztian egiten da — erabili hau inportazio masibo bat egin ondoren edo lehen aldiz IndexNow konfiguratu duzunean.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google ez da parte hartzen IndexNow-n. Mapak ezagutzen ditu robots.txt Sitemap: direktiboa erabiliz — LF-k dagoeneko konfiguratuta du. Erabili Google Search Console indexazioaren hedadura zaintzeko.','Open Search Console →'=>'Ireki Search Console →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt eguneratu da Sitemap direktiborekin.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Robots.txt fisikoa aurkitu da. LF-ren Sitemap direktiboa dago.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Webgunean robots.txt fisikoa dago. WordPress-en robots.txt birtuala — eta LF-ren Sitemap: filter-a — ez dira erabiltzen. LF-ren mapa ez da bilaketa-motorentzat iragartzen.','Add Sitemap directive to robots.txt'=>'Gehitu Sitemap zuzendaritza robots.txt-ra','Appends the following line to your existing robots.txt: %s'=>'Gehitu hurrengo lerroa zure robots.txt eguneratuan: %s','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS ezarrita dago.','Add the following line to your robots.txt manually:'=>'Gehitu hurrengo lerroa zure robots.txt-ra eskuz:','View current robots.txt'=>'Ikusi unean dagoen robots.txt','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Ez da robots.txt fisikorik aurkitu. WordPress-ek birtualki sortzen du eta LF-ren Sitemap zuzendaritza automatikoki gehitzen da.','The following directive is active in your virtual robots.txt:'=>'Hurrengo zuzendaritza aktibo dago zure birtual robots.txt-an:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Fitxategien aldaketak desgaituak daude (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'Ezin izan da robots.txt-ra idatzi. Begiratu fitxategi baimenak.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge-k WordPress Core Social Icons blokea zabaldu du dinamikoki partekatze URL-ekin. Ezarri edozein ikonoaren estekaren balioa "share:"-n eta LF-k berridazten du zuzenean partekatze URL edo JavaScript ekintzetara renderizazioan — ez da beharrezkoa kode pertsonalizatua edo hirugarren aldeko plugin bat.','Social Share settings saved.'=>'Gizarte Partekatze ezarpenak gorde dira.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'lf-social-share mu-plugin aktibo dago. Lingua Forge-ren Social Share eraikitakoak ez daude aktibo — mu-plugin-ak partekatze URL berridazketa eta JS ekintzak kudeatzen ditu.','Social Share'=>'Gizarte Partekatzea','Enable Social Share URL rewriting for Social Icons blocks'=>'Gaitu Gizarte Ikonoen blokeko URL berridazketa','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Desgaitu, dagoeneko lf-social-share mu-plugin-ak ez baititu ezarpen hau eskaintzen.','Save Social Share Settings'=>'Gorde Gizarte Partekatze Ezarpenak','How to use'=>'Nola erabili','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Bloke editorean, Gehitu Gizarte Ikonoen blokea. Ikono bakoitzerako, ireki estekaren ezarpenak eta sartu beheko "share:" balioetako bat URL gisa. Aurrealdean, LF-k ordezkatuko du orainaldiko orriaren zuzenean partekatze URL egokiarekin.','External share services'=>'Kanpoko partekatze zerbitzuak','URL to enter'=>'Sartu beharreko URL-a','Action'=>'Ekintza','Share on Facebook'=>'Partekatu Facebooken','Post on X / Twitter'=>'Mezua X / Twitter-en','Share on LinkedIn'=>'Partekatu LinkedIn-en','Send via WhatsApp'=>'Bidali WhatsApp bidez','Send via Telegram'=>'Bidali Telegram bidez','Submit to Reddit'=>'Bidali Reddit-era','Pin on Pinterest'=>'Pin egin Pinterest-en','Share on Mastodon'=>'Partekatu Mastodon-en','Share via email (mailto:)'=>'Partekatu email bidez (mailto:)','JavaScript-powered actions'=>'JavaScript bidezko ekintzak','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Kopiatu unean dagoen URL-a arbelean. Zorionekoan, "Link copied" toast bat erakusten du.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Ireki nabigatzailearen Web Share orri naturala (iOS, Android, batzuk mahaigainekoak). Itzultzen da arbelean kopiatzera, ez bada onartzen.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Erabili native partekatzea baliagarri badago; itzuli arbelean kopiatzera. Gomendatutako lehenetsia "Partekatu" botoientzat.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'Partekze URL-a beti islatzen du unean dagoen orria — ez da behar URL eskuz sartu. linguaforge_social_share_url iragazkia aukera ematen du edozein zerbitzurarako URL konponduaren gainean gainbegiratzeko.','Configuration issue: WP site language has no content on this site'=>'Konfigurazio arazoa: WP guneko hizkuntza ez du edukirik gune honetan','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'WordPress guneko hizkuntza (%1$s) "%2$s" hizkuntza kodearekin mapatzen da, baina ez da postik tagatu _lf_lang=%2$s. Honek WooCommerce produktuen kontsulta itzultzen du hutsik, produktuen irudiak huts egiten ditu, eta hizkuntza-bilaketako eduki guztiak hautsi egiten ditu.','Fix: go to'=>'Konpondu: joan','Settings → General → Site Language'=>'Ezarpenak → Orokorra → Gune Hizkuntza','and set it to one of your actual content languages (e.g. %s).'=>'eta ezarri zure eduki-hizkuntzetako baten arabera (adibidez %s).','Environment'=>'Ingurunea','Lingua Forge version'=>'Lingua Forge bertsioa','WordPress version'=>'WordPress bertsioa','PHP version'=>'PHP bertsioa','Active theme'=>'Aktibo dagoen gaia','(FSE / block theme)'=>'(FSE / blokea gaia)','(classic theme)'=>'(klasikoa gaia)','URL structure'=>'URL egitura','Subdomain (de.example.com)'=>'Azpihitzaldia (de.ejemplo.com)','Path prefix (/de/)'=>'Bidea aurrebia (/de/)','WP instance language'=>'WP instantziaren hizkuntza','not a content language — see notice above'=>'ez da eduki hizkuntza — ikusi goian oharrak','Primary content language'=>'Hizkuntza nagusia','Active languages'=>'Hizkuntza aktiboak','PHP max_execution_time'=>'PHP max_execution_time','No PHP limit'=>'Ez dago PHP mugarik','(server/FPM timeout still applies)'=>'(zerbitzariaren/FPM denbora-muga oraindik aplikatzen da)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'AI itzulpenak eta taldeko azterketak denbora asko behar izan dezakete. Gomendatzen da 120 segundoko edo gehiago.','PHP memory_limit'=>'PHP memory_limit','AI Configuration'=>'AI konfigurazioa','(active)'=>'(aktiboa)','Configured'=>'Konfiguratu da','No key'=>'Gako ez dago','— AI features are disabled.'=>'— AI ezaugarriak desgaituak daude.','Add key →'=>'Gako bat gehitu →','Light model'=>'Modelo arina','Quality model'=>'Kalitatezko modelo','Active preset'=>'Prest ezarpena','Daily quota'=>'Eguneko kuota','Unlimited'=>'Mugagabea','requests / day'=>'eskakizunak / egun','Permalink Structure'=>'Permalinka egitura','Permalink structure is compatible with Lingua Forge path routing.'=>'Permalinka egitura Lingua Forge bidearen bideratzearekin bateragarria da.','Plain permalinks are not supported.'=>'Permalinka arruntak ez dira onartzen.','Path routing requires a post-name based permalink structure. Change it in'=>'Bidearen bideratzeak permalinka egitura post-izena oinarritua behar du. Aldatu horretan','Settings → Permalinks'=>'Ezarpenak → Permalinks','Numeric permalink structure is not supported.'=>'Zenbakizko permalinka egitura ez da onartzen.','Switch to a post-name based structure in'=>'Aldatu post-izena oinarritutako egitura batean','SEO Plugins'=>'SEO pluginak','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Ez da hirugarren aldeko SEO pluginik detektatu. Lingua Forge-k guztiak handlinga egiten du SEO anitzeko emaitzetan.','Active: %s.'=>'Aktiboa: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Ikusi Ezarpenak → SEO → Konpatibilitatea, funtzionalitatearen taula osoa ikusteko.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce ez da aktiboa.','Shop'=>'Denda','Cart'=>'Saskia','Checkout'=>'Ordaintzea','My Account'=>'Nire Kontua','WooCommerce version'=>'WooCommerce bertsioa','Order storage'=>'Gordetzea','High-Performance Order Storage (HPOS)'=>'Gordetzearen ordenaren errendimendu handiko (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Taula pertsonalizatuak — LF post-meta iragazkiak ez dute eragiten eskaeretan.','Shared / compatibility mode'=>'Elkarbanatutako / konpatibilitate modua','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT sinkronizatuta — trantsizionala; LF post-meta iragazkiak CPT kopian aplikatzen dira.','Legacy post-based (CPT)'=>'Legacy post-oinarritutako (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Wp_posts-en eskaerak — ziurtatu shop_order ez dela LF bideratzean sartzen.','WcPageBridge active'=>'WcPageBridge aktiboa','Yes'=>'Bai','No — WooCommerce integration class not loaded'=>'Ez — WooCommerce integrazio klasea kargatu gabe dago','WooCommerce page translations'=>'WooCommerce orrialdeen itzulpenak','No secondary languages configured.'=>'Ez dago hizkuntza bigarrenik konfiguraturik.','Active Plugins'=>'Pluginek aktiboak','No active plugins detected.'=>'Ez dago aktibo diren pluginek detektaturik.','Version'=>'Bertsioa','_lf_lang Coverage'=>'_lf_lang Babesaldea','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'_lf_lang gabe dauden mezuak ez dira ikusgai Lingua Forge hizkuntza iragazkietan. Hau gertatu daiteke edukia inportatu edo sortu denean plugin-a aktibatu baino lehen.','All published posts have a _lf_lang value. No gaps detected.'=>'Argitaratutako mezu guztiek _lf_lang balorea dute. hutsunerik ez da detektatu.','Missing'=>'Gabe','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Ezabatu mezu mota hau hizkuntza bideraketatik — bere mezuak ez dira gehiago agertuko hemen edo _lf_lang jasoko dute. Hau ezin da automatikoki desegin.','Exclude from routing'=>'Ezabatu bideraketatik','excluded from routing'=>'bideraketatik ezabatu','Destructive action — read before proceeding'=>'Ekintza suntsitzailea — irakurri aurrerago jarraitu baino lehen','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Konpondu etiketa guztiak goian dauden bideragarri diren mezuetan _lf_lang = %s. Bideraketarik gabeko mezu motetakoak ez dira ukitzen. Hau egin besterik ez da behar edukia inportatu ondoren edo lehen aktibazioan — ez erabili hizkuntza berrantolatzeko tresna masiboan.','Repair — assign _lf_lang = %s to all routable posts above'=>'Konpondu — _lf_lang = %s ezarri goian dauden bideragarri diren mezu guztietan','Rewrite Rules'=>'Biderapenaren Arauak','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'LF-k erregistroa duen sarrera $wp_rewrite->extra_rules_top-en. 404-ak edo bideraketa gatazkak diagnostikatzeko erabilgarria. Kopiatu hauek errore txostena aurkezterakoan.','%d rule registered'=>'%d arau erregistratu da' . "\0" . '%d arau erregistratu dira','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Ez dago LF biderapen araurik aurkitu. Berrabiarazi permalinks hau ez bada espero.','Debug Info'=>'Debug Info','Copy and paste into a GitHub issue or support request.'=>'Kopiatu eta itsatsi GitHub arazo edo laguntza eskaera batean.','Copy system info'=>'Kopiatu sistema informazioa','Copied!'=>'Kopiatu da!','Repairing…'=>'Konponketa…','Repair failed.'=>'Konponketa huts egin da.','Network error.'=>'Sareko errorea.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Ezabatu mezu mota hau hizkuntza bideraketatik? Bere mezuak ez dira gehiago agertuko zerrenda honetan edo _lf_lang jasoko dute. Hau Aldaketak → Bideratzailea → Galdegaiaren iragazkiak ezarpenetan desegin dezakezu.','Excluding…'=>'Ezabatzen…','Failed to save exclusion.'=>'Ezin izan da ezarpenik gorde.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d mezu _lf_lang = %2$s etiketa duena.' . "\0" . '%1$d mezu _lf_lang = %2$s etiketa duena.','Uninstall Behaviour'=>'Desinstalazioaren portaera','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Kudeatzen du zer gertatzen den administratzaileak plugina Ezabatu plugina → Instalatutako plugina → Ezabatu aukera hautatzen duenean. Pluginaren ezarpenak eta AI cache-ak beti ezabatuko dira. Hizkuntza ezarpenak eta itzulpen harremanak mantentzen dira lehenetsita, beraz, desinstalazio edo berrinstalazio batetik jarraitu dezakeen tokian.','Uninstall setting saved.'=>'Desinstalazioaren ezarpena gorde da.','Delete content data on uninstall'=>'Ezabatu edukien datuak desinstalazioan','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Era berean, ezabatu hizkuntza ezarpenak, itzulpen harremanak, meta deskribapenak, glosarioa eta Itzulpen Memoria plugin-a desinstalatzen denean','Warning:'=>'Abisua:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Ezarrita bada, plugin-a desinstalatzen denean, hizkuntza ezarpen guztiak, itzulpen harremanak, meta deskribapenak, orrialde bakoitzeko aurre ezarpenak, AI glosarioa eta Itzulpen Memoria betiko ezabatuko dira. Hau ezin da desegin. Ez utzi markatuta, salbu eta webgunetik hizkuntza anitzaren laguntza guztia kentzen ari bazara.','Save Uninstall Setting'=>'Gorde Desinstalazioaren Ezarpena','Today'=>'Gaur','Last 7 days'=>'Azken 7 egun','Last 30 days'=>'Azken 30 egun','All time'=>'Denbora guztian','AI Usage'=>'AI Erabilera','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Token kontsumoa ezarpen, hornitzaile eta modelaren arabera. Erregistratzen da AI deien arrakastaz; Testa Konexioa pingak ez dira kontuan hartzen, beraz, ez dute totala okerra egin.','Check your account, billing, or remaining credits directly on the provider console:'=>'Kontu, fakturazio edo kreditu geldituak zuzenean hornitzailearen kontsolan egiaztatu:','Anthropic Console'=>'Anthropic Kontsola','OpenAI Platform'=>'OpenAI Plataforma','Google AI Studio'=>'Google AI Studio','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Oraindik ez da AI erabilerarik erregistratu. Editore batek itzulpena egin, meta deskribapen bat sortu edo beste AI ezaugarri bat erabili ondoren, totala hemen agertuko da.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Ez dago erabilerarik erregistratuta aukeratutako leihoan (%s). Aukeratu goiko tarte zabalagoa.','Provider'=>'Hornitzailea','Model'=>'Modeloa','Requests'=>'Eskariak','Input tokens'=>'Sarrera tokenak','Output tokens'=>'Irteera tokenak','Total tokens'=>'Token guztira','Total'=>'Guztia','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge-k WooCommerce-aren produktuen orrietan Open Graph ezaugarri espezifikoak gehitzen ditu, produktuaren URL-a Facebook, Pinterest eta antzeko plataformetan partekatzean, produktuen mota, prezioa eta eskuragarritasuna agertzeko.','WooCommerce SEO settings saved.'=>'WooCommerce SEO ezarpenak gorde dira.','Product Open Graph'=>'Produktuen Open Graph','Add WooCommerce product tags to Open Graph output'=>'Gehitu WooCommerce produktuen etiketa Open Graph irteeran','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Gaituta dagoenean, Lingua Forge-k produktu orrietan metadatu gehigarriak sortzen ditu: og:type=product, og:price:amount, og:price:currency, og:availability, eta Facebook Katalogean erabiltzen diren product: izen-espazio baliokideak.','Tags emitted'=>'Emandako etiketak','Tag'=>'Etiketa','Value source'=>'Iturri baliabidea','"product" (replaces "article")'=>'"product" ("article" ordez)','WooCommerce product price'=>'WooCommerce produktuen prezioa','WooCommerce store currency'=>'WooCommerce denda moneta','instock / oos / pending from WC stock status'=>'stock-koa / oos / WC stock-aren zain','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Prezioa eta eskuragarritasuna beti islatzen dute produktua iturri-hizkuntzan (partekatutako stock eredua). Etiketak soilik sortzen dira LF-ren Open Graph moduluak "Full" edo "Auto" moduan ezarrita dagoenean eta SEO plugin bateragarririk ez dagoenean.','Save WooCommerce SEO Settings'=>'Gorde WooCommerce SEO ezarpenak','AI Provider'=>'AI Hornitzailea','AI Usage & Cache'=>'AI Erabilera & Cache','API Keys'=>'API giltzak','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Giltzak AES-256-CBC enkriptatzen dira WordPress datu-basean gordetzen baino lehen. Enkriptazio sekretua zure WordPress autentifikazio gatibuetatik (wp-config.php) dator, beraz, testu hutseko giltzak ez dira inoiz datu-basean sartzen.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'API kredentzialak WordPress-ek %s-n kudeatzen ditu. Ez dago giltzarik Lingua Forge-k gordetzen.','Settings → Connectors'=>'Ezarpenak → Konexoreak','API Key'=>'API Giltza','Paste your API key…'=>'Itsatsi zure API giltza…','✓ Configured'=>'✓ Konfiguratu da','✗ Not configured'=>'✗ Konfiguratu gabe','Test connection'=>'Egonaldia probatu','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Utzi hutsik giltza mantentzeko. Sartu balio berria ordezkatzeko.','Remove stored key'=>'Ezabatu gordetako giltza','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Giltza hau une honetan zerbitzariko %s-k hornitzen du eta ezin da hemen ezabatu. Sartu giltza berria goian, datu-baseko balio batekin ordezkatzeko.','environment variable'=>'ingurune aldagaia','PHP constant'=>'PHP konstantea','Alternative (server-side):'=>'Alternatiba (zerbitzarian):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Giltzak definitu ditzakezu baita ere konstante edo ingurune aldaga gisa (adibidez, wp-config.php-n). Iturri hauek automatikoki erabiltzen dira, datu-baseko giltzarik ez badago.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Giltza enkriptatzeko sekretu pertsonal bat erabiltzeko (wp_salt balioa ordez), gehitu hau wp-config.php-ra:','Unknown provider.'=>'Hornitzaile ezezaguna.','No API key configured for this provider.'=>'Ez dago API giltzarik konfiguraturik hornitzaile honetan.','Could not instantiate the provider.'=>'Ezin izan da hornitzailea sortu.','Provider returned no response. Check the WordPress error log for details.'=>'Hornitzaileak erantzunik eman ez du. Egiaztatu WordPress errore erregistroa xehetasunak lortzeko.','Enter a model identifier to test.'=>'Sartu modelo-identifikadorea probatzeko.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Ez da argital edo orri argitaratuta aurkitu proba egiteko — argitaratu eduki batzuk lehenago, edo saia zaitez Quick Translate zuzenean.','(untitled)'=>'(titularik gabea)','Prompt template not found.'=>'Promtu txantiloia ez da aurkitu.','Translation failed. Please try again.'=>'Itzulpena huts egin du. Saia zaitez berriro.','The sample post has no visible text content to translate.'=>'Adibide-argitalak ez du itzultzeko testu-eduki ikusgairik.','Chunk prompt template not found.'=>'Zatiaren promtu txantiloia ez da aurkitu.','Model returned no response. Check the WordPress error log for details.'=>'Modeloak ez du erantzun eman. Egiaztatu WordPress errore-eguna xehetasunak lortzeko.','Behavior'=>'Jokabidea','Block Editor'=>'Bloke Editorea','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge-k Gutenberg bi ezaugarri mugatzen, hizkuntza anitzeko edizioaren portaera koherentea mantentzeko. Aukeratu hemen, Gutenberg / FSE gaitasun osoak behar dituzunean.','Block locking'=>'Blokearen blokeatzea','Allow editors to lock individual blocks'=>'Aukeratu editoreek bloke bana blokeatzea','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg-en canLockBlocks berriro aktibatzen du. Edizio txantiloietan erabilgarria da, kolaboratzaileek bloke zehatzak mugitu edo ezabatu ez ditzaten.','Template mode'=>'Txantiloi modua','Allow Gutenberg template-editing mode on post screens'=>'Baimendu Gutenberg-eko txantiloi editatzeko modua mezularitza pantailetan','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Re-enables supportsTemplateMode. Oinarrizko lan-fluxuak, non post mailako txantiloiak ukitzen diren, helburu da.','Compliance Preset'=>'Betetze aurrekoa','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Lege, araudi, mediku edo tekniko edukiaren gordetzeko modua. Aktibatzen denean, AI ezaugarri bakoitzak tenperatura baxu bat erabiltzen du eta behean gehitzen du sistema prompt-aren azpian — terminologia, artikulu zenbakiak, unitateak, marka izenak eta araudi hizkuntza bertan bertan gordetzen dira, ez paragrafatuak.','Global AI preset'=>'AI aurrekoa globala','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, ezaugarri bakoitzeko','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'AIren portaera lehenetsia ezartzen du webgune osoan. Post bakoitzak aldatu dezake Translatio eta Eduki Sortzailearen bidez Lingua Forge meta kutxa erabiliz.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standardak ezaugarri bakoitzaren tenperatura egokituaren erabilera du: Itzulpena T=0.2 ( zehatza), Azkar Itzulpena T=0.4, Eduki Sortzailea T=0.6 (kreatiboa). Beste aurrekoak tenperatura finkoa aplikatzen du ezaugarri guztietan.','Technical / Scientific instructions'=>'Tekniko / Zientziazko argibideak','Legal / Compliance instructions'=>'Lege / Betetze argibideak','Creative / Marketing instructions'=>'Kreatiboa / Marketin argibideak','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Utzi hutsik erabiltzeko ezarritako lehenetsia. Gorde aurretik ezarritako aldaketa ezabatzeak lehenetsia berreskuratuko du hurrengo gordetzean.','View built-in default'=>'Ikusi lehenetsia','Automatic Translation Backfill'=>'Itzulpen Automatikoa Osaketa','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Periodikoki aktibitate-hizkuntzetan itzulpena gabeko argitalak bilatzen ditu eta AI itzulpena zartzen du aurkitutako zulo bakoitzerako — eta jada eska dezakezu "Itzulpen desberdinetan" eskuz edo WP-CLI missing_translations/fill_translations komandoen bidez, automatikoki ordez behin ordutan.','Automatic backfill'=>'Osotze automatikoa','Automatically translate posts missing a language version'=>'Automatikoki itzuli hizkuntza-bertsio gabeko argitalak','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Berez desaktibatuta. Ezaugarri hau AI hornitzailearen eskaerak egiten ditu — eta lotutako API kostua gastatzen du — automatikoki eta hondoan, eskaera bakoitzeko berrespenari gabe, argital argitaratutako guztiaren arabera aktibo hizkuntzatan itzulpenik ez duena. Aktibatu hau soilik eduki-zulo guztia arretaz itzuli nahi baduzu; bestela erabili "Itzulpen desberdinetan" edo WP-CLI komandoak zure ordutegian itzultzeko.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'WooCommerce produktuak eta bariazioak ez dira inoiz sartzak, ezarpen hori zein den axola gabe. Integrazioak lingaforge_cpt_create_allowed filtroen bidez argital-tipo zehatzak debekatuak izan ditzake.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'Argital-zerrendako "Sinkronizatu" botoia Lang zutabean argital osoa berriz itzultzen du beste hizkuntza guztietan, hasierako/iturburuko argital barne itzulpenetik exekutatzen denean. Itzuli-norabide horrek desgaituta dago berez argital-tipo bakoitzerako. (WooCommerce produktuek eta bariazioak haien ezarpen berezia dute behean — hau ez du eragin neurtzen.)','Secondary-language Sync'=>'Sekundario-hizkuntza Sinkronizazioa','Allow "Sync" on a translated post to overwrite the primary post'=>'Baimendu "Sinkronizatu" itzulitako argitalean hasierako argitala gainidazteko','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Berez desaktibatuta: itzulpena batean "Sinkronizatu" klikatzea hasierako argitala gainidaztetik blokeatu egiten da. Hasierako argitaletik itzulpen guztietara sinkronizatzea beti onartuta dago ezarpen honekin axola gabe. Aktibatu hau soilik itzulpena iturburuko eduki berri bihur nahi baduzu intentzionalduz.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Hasierako-hizkuntzako produktua WooCommercek egia-iturburua funtzionala den prezioa, SKUa eta stocka, eta beti hornitzen dira bertatik shoperra ari den hizkuntza axola gabe. Hau argitalaren "Sinkronizatu" murriztapen orokorraren ezarpen berezi independentea da — bata gaitzeak bestea ez du gaitzen.','Allow "Sync" on a translated product to overwrite the primary product'=>'Baimendu "Sinkronizatu" itzulitako produktuan hasierako produktua gainidazteko','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Berez desaktibatuta: itzulitako WooCommerce produktu batean "Sinkronizatu" klikatzea blokeatuta dago, hasierako produktuaren izenburua, deskribapena eta laburpena itzultzera atzera eramango lukeelako. Hasierako produktutik itzulpen guztietara sinkronizatzea beti onartuta dago ezarpen honekin axola gabe. Aktibatu hau soilik itzulpena iturburuko eduki berri bihur nahi baduzu intentzionalduz.','General'=>'Orokorra','Light'=>'Argia','Meta Description, Excerpt Generator, quick translate'=>'Meta Deskribapena, Azpi-iturri Sortzailea, azkar itzuli','Quality'=>'Kalitatea','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Orri osoaren itzulpena, Eduki Sortzailea (eredu maila erdiak nahikoa dira)','Active Provider'=>'Hornitzaile aktiboa','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Une honetan %s konstantea heredatzen da. Hemen balioa hautatzeak gaindituko du.','WordPress AI Client — requirements:'=>'WordPress AI bezeroa — eskakizunak:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>' Orrialde osoaren itzulpena JSON-schema-murriztutako irteerarekin erabiltzen du. Horrek konektore plugin bat instalatuta eta aktibuta egotea eskatzen du (ez da API giltza bakarrik gorde behar Settings → Connectors-en). Itzulpenak huts egiten badu, PHP errore erregistroa egiaztatu erro zehatzaren inguruan, edo hornitzaile eraikitzaile batera aldatu.','Manage your account, review usage, or top up credits:'=>'Zure kontua kudeatu, erabilera berrikusi edo kredituak gehitu:','WordPress Connectors'=>'WordPress bertsioa','Models'=>'Modeloak','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Ezaugarriak bi mailatan banatzen dira. Sartu bakoitzaren identifikadore zehatza eta hornitzailearen izena. Utzi hutsik, lehenetsia erabiltzeko. Aktibo den hornitzailearen modeloak bakarrik deitzen dira exekuzioan — besteak aurretik konfiguratu behar dira aldatzeko.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Sartu edozein eremutan testua idazten hasi eta modeloen iradokizunak ikusi, edo beheko erreferentzia taula erabili. Kalitate modelu arinak eta ertainak (Haiku, GPT-4o mini, Gemini Flash) nahikoa dira itzulpen eta edukien sorkuntzarako — flagship "max" modeluak kostua gehitzen dute, kalitate minimoarekin.','active'=>'aktiboa','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>' Modeloaren hautaketa WordPressek kudeatzen du %s — Lingua Forge-k ez du identifikadore modelorik gordetzen hornitzaile honetan.','overridden'=>'gainditua','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Zure argital-bertsio berrienaren lagin labur bat itzultzen du modelo zehatza honekin — benetako, fakturatutako API deiak.','Test model'=>'Proba modeloa','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: modelo bat lehenetsira berrezartzeko, garbitu eremua eta gorde.','Available models reference'=>'Modeluen erreferentzia erabilgarri','Model ID'=>'Modelu ID','Name'=>'Izena','Tier'=>'Maila','Notes'=>'Oharra','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Katalogo hau eguneratzen da Lingua Forge bertsio bakoitzean. API giltzetan konexioa probatzeak hornitzailearen erantzun eredua ere jasotzen du eta goiko iradokizunak eguneratzen ditu.','Glossary'=>'Glosario','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Taula terminologikoaren kudeaketa erabiltzaileak hizketa bikoitzeko. Sarrera hauek gehitzen dira itzulpen sistemaren prompt-ean, AI-k termino hobesien erabilera jarraitzeko — dominen hizkuntzako lexikoan oso garrantzitsua ("kWp", "PPA", "interkonexio puntua"), markaren izenak ez dira itzuli behar, eta araudi estandarizatuen formulazioak. Bi hizketa eremuak aukera librekoa dira: utzi "Iturri hizkuntza" hutsik sartu nahi duzun hizkuntzaren araberakoa izan gabe; utzi "Helburu hizkuntza" hutsik, guztietara aplikatzeko.','Glossary entry added.'=>'Glossario sarrera gehitu da.','Glossary entry removed.'=>'Glossario sarrera ezabatu da.','Could not add entry: source term and target term are required.'=>'Ezin izan da sarrera gehitu: iturri terminoa eta helburu terminoa beharrezkoak dira.','Could not save the glossary entry.'=>'Ezin izan da glossario sarrera gorde.','Source language'=>'Hizkuntza iturriaren','— Any —'=>'— Edozein —','Target language'=>'Helburu hizkuntza','— Any target —'=>'— Edozein helburu —','Filter'=>'Filtroa','Reset'=>'Berrezarri','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Ez dago oraindik filtroarekin bat datorren glossario sarrerarik. Garbitu filtroa guztiz ikusteko edo sartu berri bat gehitzeko behean.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Oraindik ez dago glossario sarrera. Gehitu behean terminologia betetzeko itzulpenetan.','Source term'=>'Iturri terminoa','Target term'=>'Helburu terminoa','Source lang'=>'Iturri hizkuntza','Target lang'=>'Helburu hizkuntza','any'=>'edozein','Delete this glossary entry?'=>'Ezabatu glossario sarrera hau?','Add new entry'=>'Gehitu sarrera berria','The phrase as it appears in the source text.'=>'Iturri testuan agertzen den esamena.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Itzulpenan nola agertu behar duen. Iturri terminoa berdin gordetzeko AIri instrukzioa emateko, balio bera eman itzultzeko.','— Any source language —'=>'— Edozein iturri hizkuntza —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Utzi hutsik marken izenak eta hizkuntzarekiko ezberdintasunak ez diren terminoa betetzeko, itzultzen garenean.','— Any target language —'=>'— Edozein helburu hizkuntza —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Utzi hutsik, sarrera hau guztietara aplikatzeko — marka izenak, laburdurak eta beti berdin gordetzeko terminoa.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Aukerazko testuingurua editoreentzat (adibidez, "ASIC = Application-Specific Integrated Circuit; ingelesean gorde tekniko testuinguruetan").','Add entry'=>'Gehitu sarrera','Limits'=>'Muga','Authors and above (edit_published_posts)'=>'Egileak eta gehiago (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Garatzaileak eta gehiago — lehenetsia (edit_posts)','Editors and above (edit_others_posts)'=>'Editoreak eta gehiago (edit_others_posts)','Administrators only (manage_options)'=>'Administratzaileak bakarrik (manage_options)','AI Limits & Security'=>'AI Muga eta Segurtasuna','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Murriztu AI erabilera muga eta baimendu erabiltzaile rol batzuk AI bidezko deien kostuak kontrolatzeko. Erabiltzaile bakoitzeko tasa-muga gainditzen du (30 eskaera / minutua, kodean ezarrita), eta bakarrik erabiltzaile bakarraren abiadura kontrolatzen du.','Daily request limit'=>'Eguneko eskaera muga','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'AI eskaerak UTC egunean (biak Toolbar itzulpenak eta blokeko berrikuspenak) muga. Kontagailua UTC erdian berritzen da. Utzi 0, muga desgaitu nahi baduzu.','Minimum role'=>'Gutxieneko rola','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI ezaugarriak aktibatzeko aukera ematen duen WordPress gaitasun minimoa. Honek multi-autor guneetan murrizten du, Kontribuzioak edo proba kontuak AI bidezko deien kostuak saihesteko. Gainbegiratu ezazu funtzioen arabera linguaforge_required_capability filter bidez.','Translation Limits'=>'Itzulpen Muga','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Nola kontrolatu edukiaren kantitatea AIra bidaltzen dena eta erantzunaren tamaina. Utzi hutsik, balio lehenetsia erabiltzeko. Handitu balioak orri handiak moztu badira; jaitsi API kostuak murrizteko.','Model tier'=>'Modelo maila','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kalitatea (lehentasuna — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Argia (azkar eta kostu eraginkorra — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Zein modelo maila erabili itzulpen osoarentzat. Kalitatea goian ezarritako Modelo taulan konfiguratutako modeloa erabiltzen du eta gomendatzen da zehaztasun handiko, luzeak diren itzulpenetan. Aldatu Argira, azkartasuna edo kostua lehentasuna bada eta edukia laburra bada.','Max output tokens'=>'Max tokens output','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Max tokens kopurua AIk ekoiztu dezakeen itzulpen erantzun batean. Itzulpen bat isilpean moztu bada, handitu balio hau. Lehenetsia: 16.000.','Max input characters'=>'Max karaktere input','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Postaren edukia bidali zaion karakter kopururik handiena. 0 ez du mugarik — beti bidaltzen da edukia osoa (gomendatua). Ezarri balio ez-zeroa zure hornitzaileak testuinguru leiho estu bat duenean. Abisua PHP errore erregistroan idazten da edukia moztu denean.','Quick Translation'=>'Azkar Itzulpena','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Azkar Itzulpena erabilia da zatitxo/modu laburretan — pasarte laburrek eskaeraz itzultzen dira tresnabarra, editorea edo blokea popoverak erabiliz. Konfigurazio arinagoa erabiltzen du, orri osoaren itzulpenetik, erantzunak azkarrago eta kostu txikiagoa izan dadin.','Light (default — fast and cost-effective)'=>'Arina (lehena — azkar eta kostu txikia)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kalitatea (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Arin mailak model azkarrena erabiltzen du goiko Modeloak taulan konfiguratutako moduan (lehena: Haiku / Flash). Aldatu Kalitatera, zatitxoetan orri osoaren itzulpenaren zehaztasuna behar duzunean.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AI-k ekoiztu dezakeen token kopururik handiena itzulpen azkar bakoitzeko. Lehenetsia: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Sarrerako eremuak onartzen dituen karakter kopururik handiena. Lehenetsia: 8.000.','Content Generator'=>'Eduki Sortzailea','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI Eduki Sortzailearen token aurrekontua eta sarrera mugak kontrolatzen ditu. Utzi eremuak hutsik, ezarritako balioekin erabiltzeko.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'AI-k ekoiztu dezakeen token kopururik handiena sortze bakoitzeko. Handitu hori, artikulu osoak moztu gabe geratzen direnean. Lehenetsia: 8.192.','Max hints characters'=>'Gomendioen karaktere maximoa','Maximum characters read from the Hints field. Default: 2 000.'=>'Gomendioen eremutik irakurritako karaktere maximoa. Lehenetsia: 2.000.','Max context characters'=>'Testuinguru maximoa','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'AIri pasatzen zaion edukia, gomendiorik ez dagoenean, hazi testuinguru gisa. Lehenetsia: 6.000.','Maintenance'=>'Mantentze-lanak','Router'=>'Router','Primary language saved.'=>'Hizkuntza nagusia gorde da.','Permalink rules flushed successfully.'=>'Permalinka arauak arrakastaz bideratu dira.','Language uninstalled. %d post deleted.'=>'Hizkuntza desinstalatu da. %d posta ezabatu da.' . "\0" . 'Hizkuntza desinstalatu da. %d post ezabatu dira.','%d locale file removed.'=>'%d hizkuntza fitxategi ezabatu da.' . "\0" . '%d hizkuntza fitxategi ezabatu da.','%d pattern translation removed.'=>'%d eredu-itzulpena kendu da.' . "\0" . '%d eredu-itzulpena kendu dira.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d hizkuntza fitxategi ezin izan da automatikoki ezabatu (DISALLOW_FILE_MODS ezarrita dago). Ezabatu eskuz zure zerbitzarian edo WP-CLI bidez: wp language core uninstall <locale>' . "\0" . '%d hizkuntza fitxategi ezin izan da automatikoki ezabatu (DISALLOW_FILE_MODS ezarrita dago). Ezabatu eskuz zure zerbitzarian edo WP-CLI bidez: wp language core uninstall <locale>','Primary Language'=>'Hizkuntza Nagusia','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Hizkuntza nagusia beti zerbitzatzen da zure gunearen erroan — ez URL aurrizkia bide moduan, ez hizkuntza azpian domeinua moduan. Beste hizkuntzak edo /lang/ bide aurrizkia (adibidez example.com/de/) edo hizkuntza azpian domeinua (de.example.com) erabiltzen dituzte, beheko URL egitura ezarpenaren arabera.','Primary language'=>'Hizkuntza nagusia','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Hizkuntza nagusia aldatu ondoren, permalinka guztiak bota (beheko atala) URL bideraketa eguneratzeko.','Path prefix — example.com/de/'=>'Bide-izena — example.com/de/','Subdomain — de.example.com/'=>'Azpi-domein — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Azpi-domein moduak zure web zerbitzariari eskatzen dio azpi-domein hizkuntzak (adibidez, de.example.com) WordPress instalazio honetara zuzentzea. Moduak aldatzean, permalinka arauak bota eta cache-ak garbitu. Zure hasierako URL-an www badago (adibidez, www.example.com), lf_base_domain iragazkia erabili domeinaren goiko maila ezkutatzeko, azpi-domeinak era egokian eraikitzeko.','Browser language redirect'=>'Nabigatzailearen hizkuntzaren birzirkulazioa','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Bisitzaileak birzirkulatu bere nabigatzailearen Accept-Language goiburua oinarrituta','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Gaituta, lehenengo aldiz bisitatzaileek hizkuntza cookiea edo URL-an hizkuntza aurrebista ez badute, hurbilen dagoen hizkuntza bertsiora birzirkulatuko dira. Birzirkulazioa saihesten da nabigatzailearen hizkuntza aktiboen artean ez badago. Bisitari batek hizkuntza bat hautatzen duenean, cookieak lehentasuna hartzen du eta nabigatzailearen goiburua ez da kontuan hartzen bisita guztietan.','Query Filter Exclusions'=>'Galdera iragazkiak ezabatzeak','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge-k WP_Query bigarren mailako adituen esparruak mugatzen ditu (barra-berria, txantiloi-blokeak, plugin bilaketak) aktibo den hizkuntzan _lf_lang meta-konstrainta injektatuz. Hemen zerrendatutako post motak ez dira konstatze horretatik kanpo — haien kontsultak beti iragazgabetuta daude.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Contact Form 7 (wpcf7_contact_form), Flamingo kontaktuak eta sarrera-mezuak (flamingo_contact, flamingo_inbound), eta WordPress hizkuntza-pakete sinkronizazio biltegiratzea (wp_sync_storage) automatikoki baztertzen dira. Gehitu beste hirugarren aldeko post motak, edukiak hizkuntza-banaketa ez dadin egin, lerro batean edo koma bidez bereizita.','Excluded post types'=>'Ezabatutako post mota','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Post mota slug-ak komaz edo lerro berriez banatuta. Aldaketak berehala eragiten du gorde ondoren — ez da permalink-a freskatzeko beharrezkoa.','WooCommerce Integration'=>'WooCommerce bertsioa','Controls how Lingua Forge integrates with WooCommerce order processing.'=>' Nola integratzen den Lingua Forge WooCommerce eskaera prozesuarekin.','Order line item source mapping'=>' Eskaera lerro elementu iturria mapaketa','Normalize order line item product IDs to the source-language product at checkout'=>' Normalizatu eskaera lerro elementu produktuak iturri-hizkuntzako produktura ordaintzean','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>' Aktibatuta (gomendatua), WooCommerce eskaera lerro bakoitzean gordetako produktua ID iturri-hizkuntzakoa da. Honek guztiz salmenten kontaketak, WC Analytics diru-sarrera lerroak, eta hirugarren bateko ERP esportaketak produktu ID bat erreferentzia ditzaten bermatzen du SKU bakoitzeko, hizkuntza bertsio bakoitzeko bat baino gehiago ez. Trukea: "Ikusi produktua" estekak eskaera emailetan eta Nire Kontuan iturri-hizkuntzako orrira eramaten dute. Desaktibatu soilik sistema konektatu batek itzulitako produktuen IDak eskaeretan erabiltzen baditu. Erabili linguaforge_wc_order_item_source_mapping iragazkia elementu bakoitzeko overwriting-ak egiteko.','Save Router Settings'=>'Gorde Router-ezintzak','Flush Permalinks'=>'Bota Permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'WordPressen berridazketa arauak berriro sortzen ditu URL-aren aurkezpenak, hizkuntza-espezifikoak eta artxibo berridazketak bat etortzeko. Oinarrizko hizkuntza aldatzean edo hizkuntza berriak gehitzean beharrezkoa.','Flush Permalink Rules'=>'Bota Permalink Arauak','Active Languages'=>'Hizkuntzak aktiboak','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Router-ek ezagutzen dituen hizkuntzak (WordPressen locale paketeak eta oinarrizko hizkuntza). Instalatu hizkuntza pakete gehiago beheko atalean, bidegurutze eta itzulpenetarako gehiago hizkuntza erabilgarri egiteko.','%d locale pack installed.'=>'%d locale pack instalatuta.' . "\0" . '%d locale pack instalatuta.','Install a Language'=>'Hizkuntza bat instalatu','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Deskargatu eta instalatu WordPressen hizkuntza pakete nagusia WordPress.org-etik. Instalatu ondoren, locale-a URL bidegurutze eta AI itzulpen lanerako erabilgarri izango da. Eskuragarri dauden hizkuntzen zerrenda eskakizunaren arabera lortzen da — sakatu beheko botoia kargatzeko.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Hizkuntza instalazioa desgaituta dago zerbitzarian. DISALLOW_FILE_MODS konstantea wp-config.php-n ezarrita dago. Instalatu hizkuntza paketeak eskuz WP-CLI bidez: wp language core install de_DE','Load available languages'=>'Kargatu hizkuntza erabilgarriak','— select a language —'=>'— hautatu hizkuntza —','Install'=>'Instalatu','Language Setup'=>'Hizkuntza konfigurazioa','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Ez dago bigarren hizkuntzarik konfiguraturik. Instalatu hizkuntza paketea goian, txantiloiak sortzeko aukera emateko.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Hautatu hizkuntza, bere FSE txantiloiak, zatiak eta nabigazio menuak kudeatzeko.','Recreate All Languages'=>'Berriro sortu Hizkuntza Guztiak','Recreate All Languages (Templates Only)'=>'Berriro sortu Hizkuntza Guztiak (Txantiloiak Soilik)','Recreate All Languages (Template Parts Only)'=>'Berriro sortu Hizkuntza Guztiak (Txantiloi Zatiak Soilik)','Cancel'=>'Ezeztatu','Repair Template Metadata'=>'Konpondu Txantiloiaren Meta-datuak','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Konpondu Site Editor espazioa eta _lf_lang etiketa guztiak LF-eskematutako FSE txantiloietan, datu-basean gordeta. Exekutatu hau behin baino ez, lehenago Lingua Forge-ren bertsio zaharrago batetik eguneratu ondoren — WooCommerce eratorritako txantiloiak aktibo-bertsio-taldearenetik WooCommerce taldearenetara mugitzen ditu, eta ziurtatzen du eskematutako txantiloi guztiak aurkitu daitezkeela estaldura txostenetan.','Repair template metadata'=>'Konpondu txantiloiaren meta-datuak','Request failed.'=>'Eskakizuna huts egin du.','Forbidden'=>'Aurreikusi gabe','Danger Zone'=>'Arriskuen zona','Uninstall %s'=>'Desinstalatu %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Ezabatu behin betiko hizkuntza honi lotutako txantiloi guztiak, txantiloien zatiak, ereduak, nabigazio menuak, postak, orriak, post motak, produktuak eta produktu aldaketak. Era berean, WordPress lurralde pakete fitxategiak ezabatzen ditu, hizkuntza hau routerrean agertzen ez dadin. Ekintza hau ezin da desegin.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Hizkuntza hau WordPress-eko lokalizazioarekin bat dator eta ez da desinstalatu daiteke.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Ezabatu behin betiko %s? Honek hizkuntza honetan itzulitako edukia guztia ezabatuko du eta ezin da desegin.','Invalid language code.'=>'Hizkuntza kode baliogabea.','This language is protected and cannot be uninstalled.'=>'Hizkuntza hau babestuta dago eta ez da desinstalatu daiteke.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Hizkuntza instalazioa desgaituta dago zerbitzarian (DISALLOW_FILE_MODS ezarrita dago).','Invalid locale code.'=>'Hizkuntza kode baliogabea.','Language %s installed successfully.'=>'Hizkuntza %s arrakastaz instalatu da.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Hizkuntza paketea instalatzea huts egin du. Hizkuntza jada instalatuta egon daiteke, locale kodea okerra izan daiteke, edo zure zerbitzariak fitxategien idazketa bloke dezake.','Navigations'=>'Nabigazioak','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Nabigazioaren itzulpena AI hornitzaile aktibo baten beharra du. Konfiguratu API giltza API Giltzen fitxan.','Navigation'=>'Nabigazioa','Re-translate'=>'Berriz itzuli','CPT Block Patterns'=>'CPT Bloke Patternak','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Ezarritako blokeak post moten pertsonalizatuak. Erabili Itzuli botoia hizkuntza bertsioa sortzeko. Edukia itzulita hemen gordetzen da eta CPT post batean kopiatu daiteke blokea editorearen Pattern inserter-etik edo erabil daiteke Pattern Sinked (Erabilgarri Blokea) hasteko.','Pattern'=>'Patron','Post Types'=>'Post Motak','✓ Translation saved'=>'✓ Itzulpena gorde da','View'=>'Ikusi','Template Parts'=>'Txantiloien Zatiak','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Gaia-oinarritutako kopiak, hizkuntzaren arabera. Eskemak sortu ondoren, txantiloiak hizkuntzaren arabera eguneratzen dira.','Re-create all'=>'Berriro sortu guztiak','Translate all'=>'Itzuli guztiak','Fix all links'=>'Konpondu estekak guztiak','Fix all navs'=>'Zuzendu nabigazioa guztia','Part'=>'Zatia','Status / Actions'=>'Egoera / Ekintza','Create'=>'Sortu','Templates'=>'Txantiloiak','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Aktiboen gaian oinarritutako FSE txantiloiak. Sortu eta pertsonalizatu Webgune Editorean.','Create missing'=>'Sortu gabeak','Fix all parts'=>'Konpondu atal guztiak','SEO'=>'SEO','Multilingual SEO'=>'Anitzeko SEO','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Konfiguratu hreflang, Open Graph, Schema.org, sitemap-ak eta sare sozialetako parte-hartzea zure webguneko hizkuntza guztietan. Beheko atal bakoitzak SEO anitzeko atal bat kudeatzen du.','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Schema.org'=>'Schema.org','Sitemap'=>'Sitemap','Analysis'=>'Analisi','Compatibility'=>'Gaitutasuna','System'=>'Sistema','Overview'=>'Orokorra','Lingua Forge Settings'=>'Lingua Forge Ezarpenak','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge zure WordPress gunean hizkuntza anitzeko bideraketa, AI bidezko itzulpena, hreflang SEO etiketa eta hizkuntzaren switcher gehitzen ditu.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Erabili orriaren goialdeko fitxak konfigurazio bakoitza egiteko. Router fitxan egindako aldaketak berehala aplikatzen dira; AI gakoak eta ereduen konfigurazioak hurrengo AI eskaeran aplikatuko dira.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL egitura ezarpenak aldatu ondoren (bidea aurrebista ↔ azpigunea), beti bisitatu Ezarpenak → Permalinks eta sakatu Gorde Aldaketak birkargatzeko erreibatu arauak.','AI Provider Tab'=>'AI Hornitzailearen fitxa','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Hornitzaile onartuenak: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Hautatu aktibo den hornitzailea behera-datubara — hornitzaile bakarra erabiltzen da aldi berean. Sartu API gakoa hornitzaile horretarako AI ezaugarriak gaitzeko.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Gakoak atsedenaldian AES-256-GCM erabiliz enkriptatzen dira, gune-espesifikoko sekretu batekin (LINGUAFORGE_SECRET). Ez partekatu datu-base esportazioak sekretua lehenago birziklatzen ez baduzu.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI ezaugarriak aukerakoak dira. Hizkuntzen bideraketa, hreflang, hizkuntzaren switcher eta itzulpen taldea sistema guztiak lan egiten dute hornitzailearen konfigurazio gabe.','Model tiers'=>'Eredu mailak','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge-k bi modelo maila erabiltzen ditu hornitzaile bakoitzeko:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Argia: erabiltzen da meta deskribapenak eta laburpenak sortzeko — azkarra, kostu baxua.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kalitatea: erabiltzen da post itzulpen eta edukien sorkuntzarako — kalitate handiagoa, kostu handiagoa.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Utzi modelo eremua hutsik, eta erabil ezazu eraikitako lehenetsia maila horretarako. Lehenetsia testuaren ordezkoa erakusten du.','Translation Limits & Behavior'=>'Itzulpenaren mugak eta portaera','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Itzulpenaren mugak: kontrolatu zein erabiltzaile rolek aktibatu dezaketen AI itzulpena, eta ezarri hilean tokens kopurua. Aurrez aurreko kopurua gaindituz, AI deien erabilera etengo da hilabetea berritzen den arte.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Jokabidea: aukeratu AI preset (Literal, Balanced, Creative), gehitu webguneko prompt-instrukzio pertsonalizatuak, gaituta edo desgaituta utzi automatikoki postaren gordailuaren itzulpena, eta konfiguratu Itzulpen Memoria.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Itzulpen Memoriak AI emaitzak cacheatzen ditu edukien hash, hizkuntza bikote, hornitzaile eta modelaren arabera. Post bat editatzeak cachea baliogabetzen du, beraz hurrengo itzulpenak emaitza fresko bat jasoko du.','Router Tab'=>'Router-aren Fitxa','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Hizkuntza primarioa: zure edukia idatzitako hizkuntza. Itzulpen guztiak honetatik sortzen dira; aldaketa ez du postak mugitzen edo ezabatzen.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL egitura: bide-berri modua (adibide.com/de/) ez du zerbitzariko aldaketarik behar. Azpiburu modua (de.adibide.com) DNS erregistro zabaldu bat, SSL ziurtagiri zabaldu bat eta zerbitzariaren konfigurazio aldaketa bat behar du — ikusi Zerbitzariaren konfigurazio gida.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Hizkuntza aktiboak: gehitu nahi duzun hizkuntza bakoitza. Hizkuntza bakoitzak URL aurrizki edo azpihitzun bat eta hreflang etiketa bat izango du orriaren &lt;head&gt;-en.','WP site language requirement'=>'WP gunearen hizkuntza eskakizuna','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'WordPress gunearen hizkuntza (Ezarpenak → Orokorra → Gunearen Hizkuntza) zure edukirako erabiltzen dituzun hizkuntzetako batean ezarri behar da — edukiaren hizkuntza nagusia edo bigarren hizkuntzaetako bat. Ez daiteke eduki gabe dagoen hizkuntza izan.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Konfigurazio lagungarria adibidea: WP guneko hizkuntza = CA (Katalana), eduki hizkuntzak = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Konfigurazio ez lagungarria adibidea: WP guneko hizkuntza = EN (Ingelesa), eduki hizkuntzak = CA + ES soilik. Ingelesa ez da eduki hizkuntza, beraz Lingua Forge-k ezin du WP lokalizazioa mapatu edozein itzulpen taldeetara.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'WP gunearen hizkuntza ez denean: WooCommerce produktuen kontsultak hutsuneak itzultzen ditu katalogo bloke guztietan; produktuen irudiaren delegazioa huts egiten du; hizkuntza-banakako edukiaren kontsultak hausten dira; hizkuntza-aldatzailea ez daiteke egiaztatu nonbait. Router edo Sistemaren fitxan konfigurazio alerta gorria ikusten baduzu, lehenik gunearen hizkuntza zuzendu.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE lokalizazioa: eskema, itzuli, eta konpondu estekak Full Site Editing txantiloi eta zatietan zuzenean taula honetan.','Glossary Tab'=>'Glosarioaren Fitxa','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Terminoak pinatu behar dira itzuli ez daitezen edo beti modu jakin batean itzuli behar direnak (adibidez, marka-izenak, produktuen izenak, akronimoak). Glosarioaren muga AI itzulpen eskaera guztietan inposatzen dira: post itzulpena, meta deskribapena, laburpena, eta FSE txantiloi itzulpena.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Gehitu termino bat lerro bakoitzean. Biak, iturriko terminoa eta helburuko itzulpena, beharrezkoak dira. Pareta hizkuntzak zehazten du zein itzulpen lanetan aplikatzen den muga hori.','SEO Tab'=>'SEO Fitxa','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge soluzio osoa da hizkuntza anitzeko SEO-rako. Ez da beste SEO plugin edo sitemap plugin bat behar.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'LF-k ematen duena: hizkuntza bakoitzerako hreflang etiketa, Open Graph eta Twitter Card etiketa og:locale eta og:locale:alternate-rekin, Schema.org JSON-LD inLanguage azpimarraketekin, eta /lf-sitemap.xml-n hizkuntza anitzeko sitemap bat, xhtml:link alternatiba sarrerak dituena guztientzat.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Sitemap-a automatikoki iragazkia.txt-n iragartzen da. Bilaketa motor nagusiak — Google, Bing, Yandex — bertatik ezagutzen dute. Ez da eskuzko bidalketa behar.','SEO plugins and conflict avoidance:'=>'SEO pluginen eta gatazkak saihesteko:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Yoast SEO, Rank Math, All in One SEO edo SEOPress instalatuta badago, Lingua Forge detektatzen du eta egokitzen du bikoizketa outputa saihesteko. Hreflang-rako, LF hartzen du guztiaz eta pluginaren outputa ezabatzen du, pluginek ezin baitute hizkuntza anitzeko bideraketa konfigurazio egokirako hreflang zuzena sortu. Open Graph-rako, LF-k og:locale eta og:locale:alternate soilik gehitzen ditu — pluginak ezin dituen hizkuntza anitzeko seinaliak — eta OG oinarrizko multzoa pluginarentzat uzten du. Schema.org-rako, LF-k bere irteera guztia desgaitu du JSON-LD grafikoen aurkako talka saihesteko.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'SEO → Konpatibilitate fitxak bizirik dagoen detekzio egoera erakusten du eta zehatz-mehatz azaltzen du LF zer egiten duen ezaugarri bakoitzerako.','SEO Scores'=>'SEO Puntuazioak','SEO Score System'=>'SEO Puntuazio Sistema','Score computation'=>'Puntuazioaren kalkulua','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Post bakoitzak 0-100 puntu artean lortzen du sei arau-oinarritutako ereduetan: izenburua, meta deskribapena, hitzen kopurua, izenburuen egitura, irudiaren azpiko estaldura, eta barne-estekak. Hamabi puntu beti ematen dira irakasteko denbora (informazionala bakarrik). Gainerako 90 puntu beste ereduetan banatzen dira, edukien profilaren arabera pisu desberdinekin (ikusi behean).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Eredu bakoitzak lau egoeraetako bat ematen du: on (pisu osoa), abisua (50 % pisu), hutsik (0), edo informazioa (0, ez du zigorrik). 80 edo gehiago puntu lortzen duenean berdea da, 50-79 arrosa, 50 azpitik gorria.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Tituluaren puntuazio arauak (profilen guztietan): hutsik badago huts egin; 10 karaktere baino gutxiago badu ohartarazi; hitz bakarra badu ohartarazi; profilaren SERP mugapenean (60 karaktere Blogerako, 70 Produktu/Lehioarako) baino luzeagoa bada ohartarazi; gutxienez 10 karaktere, gutxienez 2 hitz eta SERP mugapenean bada onartzen da.','Content profiles and weights'=>'Edukien profilen eta pisuen kudeaketa','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Profile-ak edukien analisia egiteko muga eta pisuak egokitzen ditu. Profile-a automatikoki ebazten da; analisi bakoitzean profile-aren menuko hautapenean gainditu dezakezu.','Blog / Editorial (default)'=>'Blog / Edizioa (lehenetsia)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Titulu 15 puntu · Meta deskribapena 20 puntu · Hitzen kopurua 15 puntu · Goiburuak 20 puntu · Irudiak 10 puntu · Estekak 10 puntu. Tituluaren SERP mugapena 60 karakter; meta 120–210 karakter; hitzen kopurua 300 azpitik ohartarazten du, 100 azpitik huts egiten du; H2 beharrezkoa; barneko estekak beharrezkoak.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Auto-antzemana WooCommerce produktuetarako. Izenburua 20 puntu · Meta deskribapena 30 puntu · Hitzen kopurua 15 puntu · Izenburuak 5 puntu · Irudiak 20 puntu · Estekak 0 puntu. Izenburua SERP mugara 70 karakter; hitzen kopurua 80 azpitik ohartarazten du, 40 azpitik huts egiten du; H2 eta barne-estekak aukerazkoak dira.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Auto-antzemana hasierako orri estatikorako; eskuz aukeratu daiteke. Izenburua 20 puntu · Meta deskribapena 30 puntu · Hitzen kopurua 15 puntu · Izenburuak 10 puntu · Irudiak 15 puntu · Estekak 0 puntu. Izenburua SERP mugara 70 karakter; hitzen kopurua 150 azpitik ohartarazten du, 60 azpitik huts egiten du; H2 eta barne-estekak aukerazkoak dira.','Heading structure rules'=>'Izenburu egitura arauak','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'H1 bat behar da zehatz-mehatz. H1 normalean gaia iragartzen duen postaren izenburua da — posible bada, orainaldiko orrian irakurtzen da, eta postaren edukitik ere hartzen da alternatiba gisa.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Blog profile-ak H2 bat behar du eta ez badago, analistak lehenik H3 azpiburuak egiaztatzen ditu abisua ematen duena baino lehen. Accordion eta Details blokek H3-ra default-etan dute beren goiburuak; H3 horiek egituraren egiazkotzat hartzen dira eta emaitza onak sortzen dituzte, ez abisua.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Eduki laburra (3 paragrafo edo gutxiago) ez da inoiz zigortzen azpimarragarririk ez dagoenean, profile-aren arabera. Orrialde labur batek ez du onurarik jasotzen egituratutako goiburu behartuarekin.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Tratatu H2 H1 baliokidetzat" (Ezarpenak → SEO → Analisia): gaitu hau zure gaia argitalpenaren izenburua H2 barruan errendatzen duenean H1 ordez. Analizatzaileak lehen H2 H1-era promozionatzen du, beraz puntuazioa ez da oker penalizatua.','Score history and badges'=>'Puntuazioaren historia eta ikurrak','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Posta aztertzen den bakoitzean, puntuazioa post meta batean gordetzen da. Post zerrendako Lang zutabeak "SEO N" badge kolore-kodetua erakusten du, aztertutako edozein postentzat behintzat behin. Bi puntuazio gordeta daudenean, delta adierazlea (↑N / ↓N) aldaketa erakusten du aurreko exekuzioaren alde.','AI Usage & Cache Tab'=>'AI Erabilera eta Cache fitxa','Token usage'=>'Token erabilera','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'Erabilera taula AI tokenen kontsumoa banatzen du ezaugarriaren arabera (itzulpena, meta-deskribapena, laburpena, FSE txantiloia, talde-analisia), hornitzailearen eta ereduarentzat. Erabili datu tarte botoiak gaur, azken 7 egun, azken 30 egun edo denbora guztirako iragazteko.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Eguneko kuota (Portaera → Mugak) hemen jarraitzen da. Kuota betetzen denean, AI deiak eten egiten dira egunean zehar. Taula kuotaren erabilera nola izan den erakusten du.','Translation caching'=>'Itzulpenaren cache-a','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge-k bi cache geruza independente erabiltzen ditu AI API deien errepikapenak murrizteko:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'AI erantzun lehorrak gordetzen ditu, edukiaren hash, hizkuntza bikotea, hornitzailea, eredua eta aurrezarpena erabiliz. Cache sarrerak automatikoki baliogabetzen dira iturri postaren edukiak aldatzen direnean. Garbitu post bakoitzeko sarrerak edo cache osoa atal honetan.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Gordetzen du postaren itzulitako emaitza osoa edukiaren hash bakoitzeko. Aukeratu (gaituta dago Portaera). Azkarra da aldatutako edukiaren itzulpen errepikakorrak egiteko. Garbitu hemen, AI-k berriro pasatzeko beharra badago, edukiak aldatu edo ez.','Maintenance Tab'=>'Mantentze Fitxa','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Hizkuntzen Aldaketak: kudeatu zure .po/.mo fitxategi pertsonalizatuak Lingua Forge UI-rako. Erabili hau plugin fitxategiak zuzenean editatu beharrean — aldaketak bizirauteak iraun dezake.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: gaitu debug erregistroa AI promptak eta API erantzunak lokaleko fitxategi batean harrapatzeko. Desgaitu arazoak konpontzeko — debug moduak fitxategi bat idazten du AI eskaera bakoitzean.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Desinstalazioaren portaera: pluginak Plugins → Instalatuta dauden pluginak → Ezabatu menutik kendu denean zer ezabatu erabakitzen du. Pluginaren ezarpenak eta AI cache-ak beti ezabatzen dira. Hizkuntzaren esleipenak, itzulpen harremanak, meta deskribapenak, glosarioa eta Itzulpen Memoria mantentzen dira lehenetsita, beraz, desinstalazio edo berrinstalazio bat gertatuz gero, non utzi zenetik jarraitu dezake. Gaitu "Ezabatu edukiaren datuak desinstalazioan" soilik webgunean hizkuntza anitzeko laguntza guztiz ezabatu nahi duzunean — hau ezin da desegin.','System Tab'=>'Sistema fitxa','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Instalazioaren diagnostiko irakurgailu bakarra. Ez du konfigurazioak aldatzen — egiaztatu konfigurazioa, identifikatu arazoak, eta bildu informazioa akatsak jakinarazteko.','Sections'=>'Atalak','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge, WordPress eta PHP bertsioak; aktibo den gaia; URL egitura; WP guneko hizkuntza eta edukien hizkuntza nagusia. WP guneko hizkuntza ez bada aktibo diren eduki hizkuntzen artean, konpondu ezazu Ezarpenak → Orokorra → Gunea hizkuntza atalean.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Hornitzaile aktiboa, konfiguratutako gakoak, ereduen maila aukeraketak, aurrezarpenak eta eguneroko kuota.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Berretsi permalink egitura Lingua Forge bidearen bidearen egokitasuna. Egiturak sinpleak eta zenbakizkoak ez dira onartzen.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Zerrendatzen ditu aktibo dauden hirugarren aldeko SEO pluginak. Lingua Forge-k bere irteera egokitzen du hauek egon daudenean — ikusi Ezarpenak → SEO → Konpatibilitatea, ezaugarri bakoitzeko banaketa.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'WooCommerce bertsioa, eskaera-ereduaren modua (CPT / HPOS / partekatua), eta lau WC orrietan hizkuntza bakoitzeko itzulpenaren estaldura taula (Denda, Saskia, Ordaintzeko, Nire Kontua).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Zerrendatzen ditu post motak, \'_lf_lang\' meta baliorik gabe argitaratutako postekin. Etiketarik ez duten postak hizkuntza-banaketa guztietatik ikusezinak dira. Erabili Konpondu botoia hauei hizkuntza iturria etiketa jartzeko, edo Ezabatu post mota guztietatik hizkuntza bidearen bidez.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'$wp_rewrite->extra_rules_top-en LF-kudeatutako sarrera guztien erorketa erraztu. 404-ak edo bide-konfliktuak diagnostikatzeko erabilgarria hizkuntza berria gehitu ondoren.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Sistema laburpen testu hutseko kopia klik bakarrean. Itsatsi GitHub arazo edo laguntza eskaeran, ingurunea ikusi ahal izateko.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Akats edo portaera ezusteko bat aurkitu duzu? Ireki GitHub-en arazo bat — gehitu goiko Debug Info blokea eta zer espero zenuen eta zer gertatu den laburki deskribatu.','Open an issue →'=>'Ireki arazo bat →','Getting started'=>'Hasi','Server setup (subdomain)'=>'Zerbitzariaren konfigurazioa (azpigunea)','Translation workflow'=>'Itzulpenaren lan-fluxua','Language switcher'=>'Hizkuntzen switcher','WP-CLI reference'=>'WP-CLI erreferentzia','Integration API'=>'Integrazio API','Documentation'=>'Dokumentazioa','Report an issue on GitHub'=>'Txostena GitHub-en','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>' WordPress AI bezeroa (WP 7.0+)','Meta Description, Excerpt Generator'=>'Meta Deskribapena, Laburpen Sortzailea','Translation, Content Generator'=>'Itzulpena, Eduki Sortzailea','Testing…'=>'Testing…','✓ Connection OK'=>'✓ Konexioa ondo','✗ Failed:'=>'✗ Huts egin du: ','No response from provider — check the error log for details.'=>'Hornitzailearen erantzunik ez — egiaztatu errore erregistroa xehetasunak egiteko.','Network error — could not reach the WordPress AJAX endpoint.'=>'Sareko errorea — ezin izan da WordPress AJAX puntura iritsi.','Translating a real post with this model…'=>'Benetako argitarapena itzultzen ari da eredu honekin…','preset'=>'aurresetea','Loading…'=>'Kargatzen…','Installing…'=>'Instalatzen…','✓ Language installed.'=>'✓ Hizkuntza instalatu da.','✗ Error:'=>'✗ Akatsa:','Creating…'=>'Sortzen…','✓ All templates created.'=>'✓ Txantiloi guztiak sortu dira.','Some templates could not be created.'=>'Etxe batzuk ezin izan dira sortu.','Recreating…'=>'Berrikitzen…','✓ All templates recreated.'=>'✓ Txantiloi guztiak berrikitu dira.','Some templates could not be recreated.'=>'Txantiloi batzuk ezin izan dira berrikitu.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Honek txantiloi hau aktiboan dagoen gaiaren kopia berri batekin gainidatziko du, Gune Editorean egindako personalizazioak arbuiatuz. Hau ez da desegiteko modukoa. Jarraitu?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Honek txantiloi guztiak aktiboan dagoen gaiaren kopia berri batekin gainidatziko ditu, Gune Editorean egindako personalizazioak arbuiatuz. Hau ez da desegiteko modukoa. Jarraitu?','✓ All parts recreated.'=>'✓ Txantiloi zati guztiak berrikitu dira.','Some parts could not be recreated.'=>'Txantiloi zati batzuk ezin izan dira berrikitu.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Honek txantiloi zati hau aktiboan dagoen gaiaren kopia berri batekin gainidatziko du, Gune Editorean egindako personalizazioak arbuiatuz. Hau ez da desegiteko modukoa. Jarraitu?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Honek txantiloi zati guztiak aktiboan dagoen gaiaren kopia berri batekin gainidatziko ditu, Gune Editorean egindako personalizazioak arbuiatuz. Hau ez da desegiteko modukoa. Jarraitu?','✓ All parts created.'=>'✓ Atal guztiak sortu dira.','Some parts could not be created.'=>'Etxe batzuk ezin izan dira sortu.','✓ All translated.'=>'✓ Itzulpen guztiak egin dira.','Some translations failed.'=>'Itzulpen batzuk huts egin dute.','Review carefully — links and slugs not updated.'=>'Aztertu arretaz — estekak eta slugak ez dira eguneratu.','Fixing…'=>'Konpontzen…','✓ Links fixed.'=>'✓ Estekak konponduta.','Some link fixes failed.'=>'Etxe batzuk konponketak huts egin dute.','✓ Parts fixed.'=>'✓ Atalak konponduta.','Some part fixes failed.'=>'Atal batzuk konponketak huts egin dute.','✓ Nav refs fixed.'=>'✓ Nabigazio erreferentziak konponduta.','Some nav ref fixes failed.'=>'Nabigazio erreferentziak konponketak huts egin dute.','✓ Pattern translated.'=>'✓ Patroi itzulita.','Pattern translation failed.'=>'Patroiaren itzulpena huts egin du.','Hide'=>'Ezkutatu','Re-create all templates'=>'Berriro sortu txantiloi guztiak','Re-create all parts'=>'Berriro sortu zati guztiak','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Honek Berriro sortu txantiloi guztiak, Berriro sortu zati guztiak, Itzuli guztiak, Zuzendu zati guztiak, eta Zuzendu esteka guztiak exekutatuko ditu zure {total} hizkuntza aktibo bakoitzarentzat, bata bestearen atzetik. Aktiboan dagoen gaiaren kopia berri batekin txantiloiak eta zatiak gainidatziko ditu (Gune Editorean egindako personalizazioak arbuiatuz) eta edukia berriro itzuliko du — horietako bat ez da desegiteko modukoa. Itzuli guztiak benetako AI API deiak egiten ditu txantiloi eta zati bakoitzarentzat, eta hau denbora hartuko du eta zure hornitzailearen arabera kostuak izan ditzake. Jarraitu?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Honek Berriro sortu txantiloi guztiak, Itzuli guztiak, Zuzendu zati guztiak, eta Zuzendu esteka guztiak exekutatuko ditu zure {total} hizkuntza aktibo bakoitzarentzat, bata bestearen atzetik — txantiloi zatiak (goiburu, oinak, etab.) untxatuta geratuko dira. Aktiboan dagoen gaiaren kopia berri batekin txantiloiak gainidatziko ditu (Gune Editorean egindako personalizazioak arbuiatuz) eta edukia berriro itzuliko du — horietako bat ez da desegiteko modukoa. Itzuli guztiak benetako AI API deiak egiten ditu txantiloi bakoitzarentzat, eta hau denbora hartuko du eta zure hornitzailearen arabera kostuak izan ditzake. Jarraitu?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Honek Berriro sortu zati guztiak (goiburuak, oinak, eta beste txantiloi zatiak) exekutatuko ditu zure {total} hizkuntza aktibo bakoitzarentzat, bata bestearen atzetik. Aktiboan dagoen gaiaren kopia berri batekin txantiloi zatiak gainidatziko ditu, Gune Editorean egindako personalizazioak arbuiatuz. Hau ez da desegiteko modukoa. Jarraitu?','Starting…'=>'Hasten…','Processing {lang} ({index} of {total}) — {step}…'=>'Prozesatzen {lang} ({index} / {total}) — {step}…','Cancelled.'=>'Bertan behera utzia.','{done} of {total} languages processed.'=>'{done} / {total} hizkuntza prozesatu dira.','⚠ Done with issues.'=>'⚠ Amaitu arazoekin.','✓ All {total} languages processed.'=>'✓ {total} hizkuntza guztiak prozesatu dira.','Built-in preset instructions:'=>'Prestatutako ezarpenak: ','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Ez da prestatutako ezarpenik — AI ezaugarriek beren ezarpenak erabiltzen dituzte. Bete beheko Pertsonalizatutako aginduen eremua zure webguneko arau propioak gehitzeko.','Modified'=>'Aldatuta','edit'=>'Editatu','No published posts found for the selected filters.'=>'Ez da argitaratutako postik aurkitu hautatutako iragazkietan.','Just now'=>'Orain gutxi','Score'=>'Puntuazioa','Source title'=>'Iturri izenburua','Multilingual SEO overview'=>'Multilingual SEO ikuspegi','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Puntuazioak seinalea dira, ez epai. Eduki batzuk egiturazko mugak dituzte — oso orri laburrak, azalpen orriak gutxi duten orriak, edo helburua nabigazioa den orriak, naturan, puntuazio baxuagoa izan dezakete. Erabili ikuspegi hau hizkuntzen arteko benetako parekidetasun hutsak identifikatzeko, ez zenbaki bat jarraitzeko.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Hau WooCommerce sistema orria da (Denda, Saskia, Ordaintzeko, etab.). Eduki hori WooCommerce-k kudeatzen du — puntuazioa seinalen egiturazkoak bakarrik dira, ez SEO eduki editagarriak.','Settings'=>'Ezarpenak','You do not have permission to manage these settings.'=>'Ez duzu baimenik ezarpen hauek kudeatzeko.','Lingua Forge — Settings'=>'Lingua Forge — Ezarpenak','Settings saved.'=>'Ezarpenak gorde dira.','Save Settings'=>'Gorde Ezarpenak','Standard'=>'Estándarra','Technical / Scientific'=>'Teknikoa / Zientzia','Legal / Compliance'=>'Juridikoa / Betetze','Creative / Marketing'=>'Sortzailea / Marketina','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — Ezarpenak','Lingua Forge AI Usage Statistics'=>'Lingua Forge Ezarpenak','Date'=>' Data','Request count'=>'Eskaera kopurua','Full Article'=>'Artikulu osoa','Introduction only'=>'Sarrera soil','Structured Outline'=>'Eskema antolatu','Generate Content'=>'Sortu Edukia','Hints'=>'Gomendioak','Key points, ideas, or structure to build from…'=>'Puntu nagusiak, ideiak edo eraikitzeko egitura...','Tone'=>'Tona','Output'=>'Irteera','Generate Excerpt'=>'Sortu Aipamena','Generate Meta Description'=>'Sortu Meta Deskribapena','Translate Content'=>'Itzuli Edukia','Mode'=>'Modua','Full post'=>'Post osoa','Translate chunk'=>'Itzuli zatia','Target Language'=>'Hizkuntza Helburu','Text to translate'=>'Itzuli beharreko testua','Paste a footnote, sentence, or any snippet here…'=>'Itsatsi ohar, esaldi edo zati hau...','Also generate meta description'=>'Era berean, sortu meta deskribapena','Translated Labels'=>'Etiketak itzulita','Attribute label displayed in this language. Leave empty to use the default label.'=>'Hizkuntza honetan erakutsitako atributu etiketa. Utzi hutsik lehenetsitako etiketa erabiltzeko.','Translate all labels (AI)'=>'Itzuli etiketa guztiak (AI)','Insufficient permissions.'=>'Baimenak ez dira nahikoak.','All labels already translated.'=>'Etiketak guztiak dagoeneko itzuli dira.','%d label(s) translated.'=>'%d etiketa itzuli da.','Translation failed. Check the browser console.'=>'Itzulpenak huts egin du. Kontrolatu arakatzailearen kontsola.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Ezin izan da idatzi produktua %1$d-ra: itzulitako bertsioa da (hizkuntza: %2$s)%3$s. Datu operatiboak (prezioa, stocka, SKU, dimentsioak) iturri produktuan eguneratu behar dira. Eguneratu iturri produktua ID bidez: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Translated Names'=>'Izendapenak itzuli','Name displayed in this language. Leave empty to use the source name.'=>'Izena hizkuntza honetan erakutsia. Utzi hutsik itzultzaile izena erabiltzeko.','Translate all tags (AI)'=>'Itzul ezazu tag guztiak (AI)','Translate all categories (AI)'=>'Itzuli kategoriak guztiak (AI)','Translate all %s terms (AI)'=>'Itzuli %s termino guztiak (AI)','Translate all terms (AI)'=>'Itzul ezazu termino guztiak (AI)','Invalid taxonomy.'=>'Taxonomia baliogabea.','No terms found.'=>'Ez da termorik aurkitu.','%d term(s) translated.'=>'%d terminoa itzuli da.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d dagoeneko itzulita — <a href="#" class="lf-force-translate">bultzada berriro itzuli</a>','%1$d translated, %2$d skipped.'=>'%1$d itzuli da, %2$d baztertu da.','Order placed in language: %s'=>'Eskaera egina hizkuntzean: %s','Invalid API key — double-check the key entered in the AI Provider settings.'=>'API gako baliogabea — egiaztatu berriro sartu duzun gakoa AI Hornitzailearen ezarpenetan.','Payment required — your account has no remaining credits.'=>'Ordainketa beharrezkoa — zure kontuak kreditu gerorik ez du.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Sarbidea galarazia — zure kontua suspentsan egon daiteke edo gakoa ez du beharrezko baimenik.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Muga ezarri da — eskaera asko bidali zaizkio hornitzaileari; itxaron une bat eta saiatu berriro.','Provider service temporarily unavailable — try again in a moment.'=>'Hornitzailearen zerbitzua aldi baterako ez dago erabilgarri — saiatu berriro une batean.','Provider error (HTTP %1$d): %2$s'=>'Hornitzailearen errorea (HTTP %1$d): %2$s','Unexpected provider error (HTTP %d).'=>'Erdigune hornitzailearen errore ezustekoa (HTTP %d).','No API key configured — enter your key in the AI Provider settings.'=>'Ez da API gako konfiguratu — sartu zure gakoa AI Hornitzailearen ezarpenetan.','Network error — could not reach the provider: %s'=>'Sareko errorea — ezin izan da hornitzailea iritsi: %s','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Kredituak ez daude geratzen — gehitu zure OpenAI kontua platform.openai.com/account/billing-en.','WordPress AI Client requires WordPress 7.0 or later.'=>' WordPress AI bezeroak WordPress 7.0 edo berriagoa behar du.','No user message found in the message array.'=>' Ez dago mezua array-an erabiltzaile-mezurik aurkitu.','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>' Ez dago testu-generazio modelorik eskuragarri. Konfiguratu AI hornitzaile bat Settings → Connectors-en.','Too many AI requests. Please retry in %d seconds.'=>'AI eskaera gehiegi. Saiatu berriro %d segundo barru.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'AI egutegiko kuota bete da (%1$d eskaera). Resetatzen da %2$s UTC-tan.','View Lingua Forge details'=>'Ikusi Lingua Forge xehetasunak','View details'=>'Ikusi xehetasunak','Visit plugin site'=>'Bisita ezarpenen webgunea','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>' Lingua Forge eguneraketa blokeatuta: deskargatzeko ostalaria "%s" ez dago onartzen diren zerrendan.','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>' Lingua Forge eguneraketa blokeatuta: deskargatutako paketearen SHA-256 ez dator bat manifestarekin. Fitxategia manipulatu izan daiteke.','Exclude from navigation menus'=>'Ezabatu nabigazio menuetatik','Apply to all language versions'=>'Aplicatu hizkuntza guztietara','Noindex (hide this language version from search engines)'=>' Noindex (gorde ezazu hizkuntza bertsio hau bilatzaileetatik ezkutatzeko)','%d language not yet linked'=>'%d hizkuntza oraindik lotu gabe' . "\0" . '%d hizkuntza oraindik lotu gabe','This is the source page. Footnotes are edited directly in the block editor.'=>'Hau da iturri orria. Ohar-oinak zuzenean editatzen dira blokea editorean.','No source page linked yet.'=>'Oraindik ez dago iturri orririk lotuta.','The source page has no footnotes.'=>'Iturri orriaren ohar-oinik ez dago.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Ohar-oin hauek iturri orritik datoz eta hemen agertzen dira erreferentzia gisa soilik. Gehitu hauek orri honetan blokea editorea erabiliz.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d hizkuntzaz lokalizatutako txantiloi(ak) %2$s gaia izeneko gaiaren barruan gordeta daude, baina une honetan ez daude aktibo. Aktibatu nahi baduzu, gai hori berriro aktibatu beharko duzu. Itzulpenak gai berri horretara eramateko, berriro sortu <strong>Ezarpenak → Lingua Forge → Router → FSE eskema</strong> bidez.','Scanning posts for missing or out-of-sync featured images…'=>'Argitalpenak bilatzen ari da falta diren edo sinkronizatuta ez dauden destacatutako irudientzat…','Re-scanning…'=>'Berrikuspen…','Scan failed: '=>'Eskaneaketa huts egin du: ','unknown error'=>'Errorea ezezaguna','Scan request failed. Please try again.'=>'Eskaneatzeko eskaera huts egin du. Saiatu berriro.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ {lang} ez da aurkitu. Ziurtatu itzuli diren post guztiek hizkuntza metadatuan {lang} ezarrita dutela.','✅ All <strong>{lang}</strong> featured images are already in sync with their source post. Scanned <strong>{scanned}</strong> post(s).'=>'✅ {lang} irudi nabarmendu guztiak jada sinkronizatuta daude beren jatorrizko postarekin. Aztertu da {scanned} post(a).','Found <strong>{n}</strong> post(s) missing or out of sync with their source featured image, out of <strong>{scanned}</strong> scanned for <strong>{lang}</strong>.'=>'Aurkitutako {parts} {total} postetan eta {scanned} aztertu direnetan {lang} hizkuntzarako.','Post'=>'Posta','Current'=>'Unean','Source (EN)'=>'Iturri terminoa','None'=>' Bat ere ez','Copy from source'=>'Kopiatu segurtasun gunean','Copying…'=>'Aplikatzen…','✅ Copied'=>'✅ Kopiatua','❌ Failed'=>'❌ Huts egin du','Done — {done} of {total} post(s) fixed.'=>'Eginda — {done} post eta orri {total} konponduta.','Fixing {n} / {total}…'=>'{n} / {total} konpontzen…','Fix Featured Images'=>' Irudi Nabarmenduak Konpondu','Featured Image Fixer'=>' Irudi Nabarmendu Konpontzailea','Fix All'=>'Konpondu Guztiak','Re-scan'=>'Birbideratu','Scanning posts for broken language links…'=>'Hitz egiten ari diren postak hizkuntza loturak hausten saiatzen…','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Ez da hautsi edo txantiloiak ez datoz bat aurkitu. Ikusi <strong>{scanned}</strong> post eta orri — guztiak ondo daude. Txantiloi zatien loturak (goiburua, oinarria, alboko barra) ez dira hemen sartzen — erabili Fix Template Parts botoia horiek banan banan egiaztatzeko.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> auto-konpondu daitezkeen lotura','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> eskuz berrikusi behar diren lotura','and'=>'eta','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Aurkitutako {parts} {total} postetan eta {scanned} aztertu direnetan {lang} hizkuntzarako.','link(s)'=>'lotura(ak)','Fix'=>'Konpondu','✅ Fixed ({n})'=>'✅ Konponduta ({n})','⚠ No changes — re-scan?'=>'⚠ Ez da aldaketarik — berriro eskaneatu?','⚠ No changes'=>'⚠ Ez da aldaketarik','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} ez zuen ordezkagarri dauden loturarik — berriro eskaneatu ikusteko)}','URL could not be mapped to a post — check the link target exists'=>'URL ez da mapatu post batera — egiaztatu helburu lotura existitzen dela','No {lang} translation registered (TRID missing)'=>'Ez dago {lang} itzulpenik erregistratuta (TRID falta)','Translation found but permalink could no